import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 14,
  code: "2CH",
  name: "2 Cronici",
  chapters: {
    1: ["Solomon, fiul lui David, s-a întărit în domnie; DOMNUL Dumnezeul lui a fost cu el; și l-a înălțat din ce în ce mai mult.", "Solomon a vorbit întregului Israel, căpeteniilor peste mii și sute, judecătorilor, mai marilor întregului Israel, căpeteniilor caselor părintești;", "și Solomon s-a dus cu toată adunarea la înălțimea de la Gabaon. Acolo se afla Cortul întâlnirii lui Dumnezeu, făcut în pustiu de Moise, robul DOMNULUI.", "Dar chivotul lui Dumnezeu fusese mutat de David din Chiriat-Iearim la locul pe care i-l pregătise, căci îi întinsese un Cort la Ierusalim.", "Tot acolo se afla, înaintea Cortului DOMNULUI, altarul de aramă pe care-l făcuse Bețaleel, fiul lui Uri, fiul lui Hur; Solomon și adunarea au căutat sfat acolo.", "Solomon s-a suit acolo la altarul de aramă care era înaintea Cortului întâlnirii și a adus pe el DOMNULUI o mie de arderi de tot.", "În timpul nopții, Dumnezeu S-a arătat lui Solomon și i-a zis: „Cere ce vrei să-ți dau.”", "Solomon a răspuns lui Dumnezeu: „Tu ai arătat o mare bunăvoință tatălui meu, David, și m-ai pus să domnesc în locul lui.”", "Acum, DOAMNE Dumnezeule, împlinească-se făgăduința Ta făcută tatălui meu David, fiindcă m-ai pus să domnesc peste un popor mare la număr, ca pulberea pământului!", "„Dă-mi, dar, înțelepciune și pricepere, ca să știu cum să mă port în fruntea acestui popor! Căci cine ar putea să judece pe poporul Tău, pe poporul acesta atât de mare?”", "Dumnezeu a zis lui Solomon: „Fiindcă dorința aceasta este în inima ta, fiindcă nu ceri nici bogății, nici averi, nici slavă, nici moartea vrăjmașilor tăi, nici chiar o viață lungă, ci ceri pentru tine înțelepciune și pricepere ca să judeci pe poporul Meu, peste care te-am pus să domnești,”", "„înțelepciunea și priceperea îți sunt date. Îți voi da, pe deasupra, bogății, averi și slavă, cum n-a mai avut niciodată niciun împărat înaintea ta și cum nici nu va mai avea după tine.”", "Solomon s-a întors la Ierusalim, după ce a părăsit înălțimea de la Gabaon și Cortul întâlnirii. Și a domnit peste Israel.", "Solomon a strâns care și călărime; avea o mie patru sute de care și douăsprezece mii de călăreți, pe care i-a așezat în cetățile unde ținea carele și la Ierusalim lângă împărat.", "Împăratul a făcut argintul și aurul tot atât de obișnuite la Ierusalim ca pietrele, și cedrii tot atât de obișnuiți ca sicomorii care cresc în câmpie.", "Solomon își aducea caii din Egipt și din Cue; negustorii împăratului îi cumpărau din Cue, la un preț.", "Aduceau din Egipt și exportau un car cu șase sute de sicli de argint și un cal cu o sută cincizeci de sicli. Tot așa exportau și pentru toți împărații hetiților și pentru împărații Siriei."],
    2: ["Solomon a poruncit să se zidească o Casă Numelui DOMNULUI și o casă împărătească pentru el.", "Solomon a numărat șaptezeci de mii de oameni, ca să ducă sarcinile, optzeci de mii, ca să taie pietre pe munte, și trei mii șase sute, ca să-i privegheze.", "Solomon a trimis să spună lui Hiram, împăratul Tirului: „Fă-mi și mie cum ai făcut tatălui meu, David, căruia i-ai trimis cedri, ca să-și zidească o casă de locuit.”", "Iată, eu înalț o Casă Numelui DOMNULUI Dumnezeului meu, ca să I-o închin Lui, să ard înaintea Lui tămâie mirositoare, să aduc necurmat în ea pâinile pentru punerea înainte și să aduc arderile de tot de dimineață și de seară în zilele de Sabat, de lună nouă și de sărbătoare ale DOMNULUI Dumnezeului nostru, după o lege veșnică pentru Israel.", "Casa pe care o voi zidi trebuie să fie mare, căci Dumnezeul nostru este mai mare decât toți dumnezeii.", "Dar cine poate să-I zidească o Casă, când cerurile și cerurile cerurilor nu-L pot cuprinde? Și cine sunt eu, ca să-I zidesc o Casă, decât doar ca să ard tămâie înaintea Lui?", "Trimite-mi, dar, un om iscusit în lucrarea aurului, argintului, aramei și fierului, a materiilor vopsite în purpură, a materiilor de culoarea cârmâzului și de culoare albastră și care să cunoască săpătura în lemn, ca să lucreze cu meșterii iscusiți care sunt la mine în Iuda și la Ierusalim și pe care i-a ales tatăl meu, David.", "Trimite-mi din Liban și lemn de cedru, de chiparos și de algum; căci știu că slujitorii tăi se pricep să taie lemne din Liban. Iată că slujitorii mei vor fi cu ai tăi.", "Să mi se pregătească lemn din belșug, căci Casa pe care o voi zidi va fi mare și măreață.", "„Slujitorilor tăi care vor tăia, care vor doborî jos lemnele, le voi da douăzeci de mii de cori de grâu treierat, douăzeci de mii de cori de orz, douăzeci de mii de bați de vin și douăzeci de mii de bați de untdelemn.”", "Hiram, împăratul Tirului, a răspuns astfel, printr-o scrisoare pe care a trimis-o lui Solomon: „Pentru că DOMNUL iubește pe poporul Său, de aceea te-a pus împărat peste ei.”", "Hiram a mai zis: „Binecuvântat să fie DOMNUL Dumnezeul lui Israel care a făcut cerurile și pământul, că a dat împăratului David un fiu înțelept, priceput și cuminte, care va zidi o casă DOMNULUI și o casă împărătească pentru el!”", "Îți trimit, dar, un om meșter și priceput, pe Huram-Abi,", "fiul unei femei dintre fetele lui Dan și al unui tată tirian. El este meșter pentru lucrările în aur, în argint, în aramă și în fier, în piatră și în lemn, în materii vopsite în purpură și în albastru, în materii de vison și cârmâz, și pentru orice fel de săpături și lucruri meșteșugite care i se dau de făcut, ca să lucreze cu oamenii tăi iscusiți și cu oamenii iscusiți ai domnului meu David, tatăl tău.", "Acum, domnul meu să trimită slujitorilor tăi grâul, orzul, untdelemnul și vinul de care a vorbit.", "„Și noi vom tăia lemne din Liban atât cât vei avea nevoie; ți le vom trimite pe mare în plute până la Iafo, și de acolo tu le vei sui la Ierusalim.”", "Solomon a numărat pe toți străinii care erau în țara lui Israel și a căror numărătoare fusese făcută de tatăl său, David. S-au găsit o sută cincizeci și trei de mii șase sute.", "Și a luat din ei șaptezeci de mii, ca să poarte sarcinile, optzeci de mii, să taie pietre pe munte, și trei mii șase sute, ca să privegheze și să îndemne pe popor la lucru."],
    3: ["Solomon a început zidirea Casei DOMNULUI la Ierusalim, pe muntele Moria, unde DOMNUL i Se arătase tatălui său David, în locul pe care-l pregătise David în aria lui Ornan, iebusitul.", "A început să zidească în a doua zi a lunii a doua, în al patrulea an al domniei lui.", "Iată pe ce temelii a zidit Solomon Casa lui Dumnezeu: Lungimea, în coți de măsura cea veche a coților, era de șaizeci de coți, iar lățimea, de douăzeci de coți.", "Pridvorul dinainte avea douăzeci de coți lungime, cât era de lată Casa, și o sută douăzeci de coți înălțime; Solomon l-a acoperit pe dinăuntru cu aur curat.", "A căptușit încăperea cea mare cu lemn de chiparos, a acoperit-o cu aur curat și a săpat pe ea finici și împletituri de lănțișoare.", "A acoperit Casa cu pietre scumpe ca podoabă; și aurul era aur din Parvaim.", "A acoperit cu aur Casa, bârnele, pragurile, pereții și ușile și a pus să sape heruvimi pe pereți.", "A făcut casa Locului Preasfânt. Ea era lungă de douăzeci de coți, cât lărgimea Casei, și largă de douăzeci de coți. A acoperit-o cu aur curat, care prețuia șase sute de talanți.", "Greutatea aurului pentru cuie se ridica la cincizeci de sicli. A îmbrăcat cu aur și odăile de sus.", "A făcut în casa Locului Preasfânt doi heruvimi săpați și i-a acoperit cu aur.", "Aripile heruvimilor aveau o lungime de douăzeci de coți. Aripa celui dintâi, lungă de cinci coți, atingea zidul Casei; și cealaltă aripă, lungă tot de cinci coți, atingea aripa celui de-al doilea heruvim.", "Aripa celui de-al doilea heruvim, lungă de cinci coți, atingea zidul Casei; și cealaltă aripă, lungă tot de cinci coți, se unea cu aripa celui dintâi heruvim.", "Aripile acestor heruvimi, întinse, aveau douăzeci de coți. Ei stăteau în picioare, cu fața întoarsă spre Casă.", "A făcut perdeaua albastră, purpurie și cărămizie și de in subțire și a lucrat heruvimi pe ea.", "A făcut înaintea Casei doi stâlpi de treizeci și cinci de coți înălțime, cu un cap de cinci coți în vârful lor.", "A făcut niște lanțuri în Locul Preasfânt și le-a pus pe vârful stâlpilor. Apoi a făcut o sută de rodii pe care le-a pus pe lanțuri.", "A așezat stâlpii în partea dinainte a Templului, unul la dreapta, și altul la stânga; a numit pe cel de la dreapta Iachin, și pe cel de la stânga, Boaz."],
    4: ["A făcut un altar de aramă, lung de douăzeci de coți, lat de douăzeci de coți și înalt de zece coți.", "A făcut marea turnată. Ea avea zece coți de la o margine la alta, era rotundă de tot, înaltă de cinci coți, și un fir de treizeci de coți ar fi înconjurat-o.", "Sub marginea ei, de jur împrejur, erau niște chipuri de boi, câte zece de fiecare cot, de jur împrejurul mării; boii, așezați pe două rânduri, erau turnați dintr-o singură bucată cu ea.", "Era așezată pe doisprezece boi, dintre care trei, întorși spre miazănoapte, trei, întorși spre apus, trei, întorși spre miazăzi și trei, întorși spre răsărit; marea era așezată pe ei, și toată partea dinapoi a trupurilor lor era înăuntru.", "Grosimea ei era de un lat de mână, și marginea, ca marginea unui pahar, era făcută în felul unei flori de crin. Puteau să încapă în ea trei mii de bați.", "A făcut zece lighene și a pus cinci la dreapta și cinci, la stânga, ca să slujească la curățări: în ele se spălau feluritele părți ale arderilor de tot. Marea era pentru spălarea preoților.", "A mai făcut zece sfeșnice de aur, după porunca privitoare la ele, și le-a așezat în Templu, cinci, la dreapta și cinci la stânga.", "A mai făcut zece mese și le-a așezat în Templu, cinci, la dreapta și cinci, la stânga. A mai făcut o sută de potire de aur.", "A mai făcut curtea preoților și curtea cea mare, cu porțile ei, ale căror aripi le-a acoperit cu aramă.", "A așezat marea în partea dreaptă, la miazăzi-răsărit.", "Hiram a făcut oalele, lopețile și potirele. Astfel a isprăvit Hiram lucrarea pe care i-a dat-o împăratul Solomon s-o facă pentru Casa lui Dumnezeu:", "doi stâlpi, cupele și cele două capiteluri de pe vârful stâlpilor; cele două rețele care acopereau cele două cupe ale capitelurilor de pe vârful stâlpilor;", "cele patru sute de rodii pentru cele două rețele, câte două șiruri de rodii pentru fiecare rețea, pentru acoperirea celor două cupe ale capitelurilor de pe stâlpi;", "temeliile și lighenele de pe temelii;", "marea și cei doisprezece boi de sub ea;", "oalele, lopețile și furculițele. Toate aceste unelte, pe care le-a dat împăratul Solomon lui Huram-Abi să le facă pentru Casa DOMNULUI, erau de aramă lustruită.", "Împăratul a pus să le toarne în câmpia Iordanului, într-un pământ cleios, între Sucot și Țereda.", "Solomon a făcut toate aceste unelte în număr atât de mare, încât nu s-a putut cerceta greutatea aramei.", "Solomon a mai făcut toate celelalte unelte pentru Casa lui Dumnezeu: altarul de aur, mesele pe care se puneau pâinile pentru punerea înaintea DOMNULUI;", "sfeșnicele și candelele lor de aur curat, care trebuiau aprinse, după poruncă, înaintea Locului Preasfânt,", "florile, candelele și mucările de aur, de aur foarte curat;", "mucările, potirele, ceștile și cățuile de aur curat; iar ușile dinăuntru ale Casei, la intrarea Locului Preasfânt, și ușile Casei, la intrarea Templului, erau de aur."],
    5: ["Astfel a fost isprăvită toată lucrarea pe care a făcut-o Solomon pentru Casa DOMNULUI. Apoi a adus argintul, aurul și toate uneltele pe care le închinase DOMNULUI, tatăl său, David, și le-a pus în vistieriile Casei lui Dumnezeu.", "Atunci Solomon a strâns la Ierusalim pe bătrânii lui Israel și pe toate căpeteniile semințiilor, pe capii familiilor copiilor lui Israel, ca să mute din cetatea lui David, adică din Sion, chivotul legământului DOMNULUI.", "Toți bărbații lui Israel s-au adunat la împărat pentru sărbătoarea din luna a șaptea.", "Când au ajuns toți bătrânii lui Israel, leviții au ridicat chivotul.", "Au adus chivotul, Cortul întâlnirii și toate uneltele sfinte care erau în Cort: preoții și leviții le-au dus.", "Împăratul Solomon și toată adunarea lui Israel chemată la el, a stat înaintea chivotului. Au jertfit oi și boi, care nu se pot nici socoti, nici număra, din pricina mulțimii lor.", "Preoții au dus chivotul legământului DOMNULUI la locul lui, în sfântul locaș al Casei, în Locul Preasfânt, sub aripile heruvimilor.", "Heruvimii aveau aripile întinse peste locul chivotului și acopereau chivotul și drugii lui pe deasupra.", "Drugilor li se dăduse o astfel de lungime încât capetele lor se vedeau la o depărtare de chivot dinaintea Sfântului Locaș, dar nu se vedeau de afară. Chivotul a fost acolo până în ziua de azi.", "În chivot nu erau decât cele două table pe care le pusese acolo Moise, în Horeb, când a făcut DOMNUL legământ cu copiii lui Israel, la ieșirea lor din Egipt.", "În clipa când au ieșit preoții din Locul Sfânt (căci toți preoții de față se sfințiseră, fără să mai țină șirul cetelor,", "și toți leviții care erau cântăreți: Asaf, Heman, Iedutun, fiii și frații lor, îmbrăcați în in subțire, stăteau la răsăritul altarului cu chimvale, lăute și harpe și aveau cu ei o sută douăzeci de preoți care sunau din trâmbițe);", "și, când cei ce sunau din trâmbițe și cei ce cântau, unindu-se într-un glas ca să mărească și să laude pe DOMNUL, au sunat din trâmbițe, chimvale și celelalte instrumente și au mărit pe DOMNUL prin aceste cuvinte: „Căci este bun, căci îndurarea Lui ține în veci!” Atunci Casa s-a umplut de un nor, și anume Casa DOMNULUI.", "Preoții n-au putut să mai stea acolo ca să facă slujba, din pricina norului; căci slava DOMNULUI umpluse Casa lui Dumnezeu."],
    6: ["Atunci Solomon a zis: „DOMNUL a zis că vrea să locuiască în întuneric!”", "„Și eu am zidit o Casă care-Ți va fi locuința, un loc unde vei locui în veci!”", "Împăratul și-a întors fața și a binecuvântat toată adunarea lui Israel. Și toată adunarea lui Israel stătea în picioare.", "Și el a zis: „Binecuvântat să fie DOMNUL Dumnezeul lui Israel, care a vorbit cu gura Sa tatălui meu David și a împlinit cu mâna Sa ce spusese, când a zis:”", "„Din ziua când am scos pe poporul Meu din țara Egiptului, n-am ales nicio cetate dintre toate semințiile lui Israel, ca să se zidească acolo o Casă în care să locuiască Numele Meu, și n-am ales pe niciun om, care să fie căpetenia poporului Meu, Israel.”", "„Ci Ierusalimul l-am ales, pentru ca în el să locuiască Numele Meu, și pe David l-am ales, ca să domnească peste poporul Meu, Israel!”", "Tatăl meu, David, avea de gând să zidească o casă Numelui DOMNULUI Dumnezeului lui Israel.", "Și DOMNUL a zis tatălui meu, David: „Fiindcă ai avut de gând să zidești o Casă Numelui Meu, bine ai făcut că ai avut gândul acesta.”", "„Numai că nu tu vei zidi Casa; ci fiul tău, ieșit din tine, va zidi Numelui Meu o Casă.”", "DOMNUL a împlinit cuvântul pe care-l spusese. Eu m-am ridicat în locul tatălui meu, David, și am șezut pe scaunul de domnie al lui Israel, cum vestise DOMNUL, și am zidit o Casă Numelui DOMNULUI Dumnezeului lui Israel.", "„Am așezat în ea chivotul, în care este legământul DOMNULUI, legământul pe care l-a făcut El cu copiii lui Israel.”", "Solomon s-a așezat înaintea altarului DOMNULUI, în fața întregii adunări a lui Israel, și a întins mâinile.", "Căci Solomon făcuse o treaptă de aramă și o pusese în mijlocul curții. Ea era lungă de cinci coți, lată de cinci coți și înaltă de trei coți; a stat pe ea, a îngenuncheat în fața întregii adunări a lui Israel și a întins mâinile spre cer.", "Și a zis: „DOAMNE Dumnezeul lui Israel! Nu este Dumnezeu ca Tine, în ceruri și pe pământ: Tu ții legământul și îndurarea Ta față de robii Tăi care umblă înaintea Ta cu toată inima lor!”", "Astfel, Ți-ai ținut cuvântul dat robului Tău David, tatăl meu; și ce ai spus cu gura Ta împlinești astăzi cu mâna Ta.", "Acum, DOAMNE Dumnezeul lui Israel, ține făgăduința pe care ai făcut-o tatălui meu, David, când ai zis: „Niciodată nu vei fi lipsit înaintea Mea de un urmaș care să șadă pe scaunul de domnie al lui Israel, numai fiii tăi să ia seama la calea lor și să meargă în Legea Mea, cum ai mers tu înaintea Mea.”", "Împlinească-se, dar, DOAMNE Dumnezeul lui Israel, făgăduința pe care ai făcut-o robului Tău David!", "Dar ce! Să locuiască Dumnezeu cu adevărat împreună cu omul pe pământ? Iată că cerurile și cerurile cerurilor nu Te pot cuprinde: cu cât mai puțin această Casă pe care am zidit-o eu!", "Totuși, DOAMNE Dumnezeul meu, ia aminte la rugăciunea robului Tău și la cererea lui! Ascultă strigătul și rugăciunea pe care Ți-o face robul Tău.", "Ochii Tăi să fie zi și noapte deschiși peste Casa aceasta, peste locul despre care ai zis că acolo va fi Numele Tău! Ascultă rugăciunea pe care o face robul Tău în locul acesta!", "Ascultă cererile robului Tău și ale poporului Tău, Israel, când se vor ruga în locul acesta! Ascultă din locul locuinței Tale, din ceruri, ascultă și iartă!", "Dacă va păcătui cineva împotriva aproapelui său și se va pune peste el un jurământ, ca să-l facă să jure, și dacă va veni să jure înaintea altarului Tău, în Casa aceasta,", "ascultă-l din ceruri, lucrează și judecă pe robii Tăi: osândește pe cel vinovat și fă ca purtarea lui să cadă asupra capului lui; fă dreptate celui nevinovat și răsplătește-i după nevinovăția lui!", "Când poporul Tău, Israel, va fi bătut de vrăjmaș, pentru că a păcătuit împotriva Ta, dacă se vor întoarce la Tine și vor da slavă Numelui Tău, dacă Îți vor face rugăciuni și cereri în Casa aceasta,", "ascultă-i din ceruri, iartă păcatul poporului Tău, Israel, și adu-i înapoi în țara pe care ai dat-o lor și părinților lor.", "Când cerul va fi închis și nu va fi ploaie, din pricina păcatelor lor împotriva Ta: dacă se vor ruga în acest loc și vor da slavă Numelui Tău, și dacă se vor întoarce de la păcatele lor (pentru că-i vei fi pedepsit),", "ascultă-i din ceruri, iartă păcatul robilor Tăi și al poporului Tău, Israel, învață-i calea cea bună în care trebuie să meargă și trimite ploaie pe pământul pe care l-ai dat de moștenire poporului Tău!", "Când vor fi în țară foametea, ciuma, rugina în grâu și mălura, lăcustele de un soi sau altul, când vrăjmașul va împresura pe poporul Tău, în țara lui, în cetățile lui, când vor fi urgii sau boli de vreun fel:", "dacă un om, dacă tot poporul Tău, Israel, va face rugăciuni și cereri, și fiecare își va cunoaște rana și durerea și va întinde mâinile spre Casa aceasta,", "ascultă-l din ceruri, din locul locuinței Tale, și iartă-l; răsplătește fiecăruia după căile lui, Tu, care cunoști inima fiecăruia (căci numai Tu cunoști inima copiilor oamenilor),", "ca să se teamă de Tine și să umble în căile Tale tot timpul cât vor trăi în țara pe care ai dat-o părinților noștri!", "Când străinul care nu este din poporul Tău, Israel, va veni dintr-o țară depărtată, din pricina Numelui Tău celui mare, din pricina mâinii Tale celei tari și din pricina brațului Tău întins, când va veni să se roage în Casa aceasta,", "ascultă-l din ceruri, din locul locuinței Tale, și dă străinului aceluia tot ce-Ți va cere, pentru ca toate popoarele pământului să cunoască Numele Tău, să se teamă de Tine ca poporul Tău, Israel, și să știe că Numele Tău este chemat peste Casa aceasta pe care am zidit-o!", "Când va ieși poporul Tău la luptă împotriva vrăjmașilor lui, urmând calea pe care îi vei porunci s-o urmeze, dacă Îți vor face rugăciuni cu privirile îndreptate spre cetatea aceasta pe care ai ales-o și spre Casa pe care am zidit-o în Numele Tău,", "ascultă din ceruri rugăciunile și cererile lor și fă-le dreptate!", "Când vor păcătui împotriva Ta (căci nu este om care să nu păcătuiască) și când vei fi mâniat împotriva lor și-i vei da în mâna vrăjmașului, care-i va duce robi într-o țară depărtată sau apropiată:", "dacă își vor veni în fire în țara unde vor fi robi, dacă se vor întoarce la Tine și Îți vor face cereri în țara robiei lor și vor zice: „Am păcătuit, am săvârșit fărădelegi, am făcut rău!”", "dacă se vor întoarce la Tine din toată inima lor și din tot sufletul lor, în țara robiei lor, unde au fost duși robi, dacă-Ți vor face rugăciuni cu privirile întoarse spre țara lor, pe care ai dat-o părinților lor, spre cetatea pe care ai ales-o și spre Casa pe care am zidit-o Numelui Tău,", "ascultă din ceruri, din locul locuinței Tale, rugăciunile și cererile lor și fă-le dreptate: iartă poporului Tău păcatele făcute împotriva Ta!", "Acum, Dumnezeule, ochii Tăi să fie deschiși, și urechile să-Ți fie cu luare-aminte la rugăciunea făcută în locul acesta!", "Acum, DOAMNE Dumnezeule, scoală-Te, vino la locul Tău de odihnă, Tu și chivotul măreției Tale. Preoții Tăi, DOAMNE Dumnezeule, să fie îmbrăcați cu mântuirea, și preaiubiții Tăi să se bucure de fericire!", "„DOAMNE Dumnezeule, nu întoarce fața de la unsul Tău, adu-Ți aminte de bunătățile făgăduite robului Tău David!”"],
    7: ["Când și-a isprăvit Solomon rugăciunea, s-a coborât foc din cer și a mistuit arderea de tot și jertfele, și slava DOMNULUI a umplut casa.", "Preoții nu puteau să intre în Casa DOMNULUI, căci slava DOMNULUI umplea Casa DOMNULUI.", "Toți copiii lui Israel au văzut coborându-se focul și slava DOMNULUI peste Casă; ei și-au plecat fața la pământ pe pardoseală, s-au închinat și au lăudat pe DOMNUL, zicând: „Căci este bun, căci îndurarea Lui ține în veac!”", "Împăratul și tot poporul au adus jertfe înaintea DOMNULUI.", "Împăratul Solomon a înjunghiat douăzeci și două de mii de boi și o sută douăzeci de mii de oi. Astfel au făcut împăratul și tot poporul sfințirea Casei lui Dumnezeu.", "Preoții stăteau la locul lor, și tot astfel și leviții, cu instrumentele făcute în cinstea DOMNULUI de împăratul David pentru cântarea laudelor DOMNULUI, când i-a însărcinat David să mărească pe DOMNUL, zicând: „Căci îndurarea Lui ține în veac!” Preoții sunau din trâmbițe înaintea lor, iar tot Israelul stătea în picioare.", "Solomon a sfințit și mijlocul curții, care este înaintea Casei DOMNULUI; căci acolo a adus arderile de tot și grăsimile jertfelor de mulțumire, pentru că altarul de aramă, pe care-l făcuse Solomon, nu putea cuprinde arderile de tot, darurile de mâncare și grăsimile.", "Solomon a prăznuit sărbătoarea în vremea aceea, șapte zile, și tot Israelul a prăznuit împreună cu el; venise o mare mulțime de oameni, de la intrarea Hamatului până la pârâul Egiptului.", "În ziua a opta, au avut o adunare de sărbătoare; căci sfințirea altarului au făcut-o șapte zile, și sărbătoarea, tot șapte zile.", "În a douăzeci și treia zi a lunii a șaptea, Solomon a trimis înapoi în corturi pe popor, care era vesel și mulțumit de binele pe care-l făcuse DOMNUL lui David, lui Solomon și poporului Său, Israel.", "Când a isprăvit Solomon Casa DOMNULUI și casa împăratului și a izbutit în tot ce-și pusese de gând să facă în Casa DOMNULUI și în casa împăratului,", "DOMNUL S-a arătat lui Solomon noaptea și i-a zis: „Îți ascult rugăciunea și aleg locul acesta drept Casa unde va trebui să Mi se aducă jertfe.”", "Când voi închide cerul și nu va fi ploaie, când voi porunci lăcustelor să mănânce țara, când voi trimite ciuma în poporul Meu:", "dacă poporul Meu, peste care este chemat Numele Meu, se va smeri, se va ruga și va căuta fața Mea și se va abate de la căile lui rele, îl voi asculta din ceruri, îi voi ierta păcatul și-i voi tămădui țara.", "Ochii Mei vor fi deschiși de acum, și urechile Mele vor fi cu luare-aminte la rugăciunea făcută în locul acesta.", "Acum, aleg și sfințesc Casa aceasta, pentru ca Numele Meu să locuiască în ea pe vecie, și voi avea întotdeauna ochii și inima Mea acolo.", "Și tu, dacă vei umbla înaintea Mea cum a umblat tatăl tău David, făcând tot ce ți-am poruncit și dacă vei păzi legile și poruncile Mele,", "voi întări scaunul de domnie al împărăției tale, cum am făgăduit tatălui tău, David, când am zis: „Niciodată nu vei fi lipsit de un urmaș care să domnească peste Israel.”", "Dar, dacă vă veți abate, dacă veți părăsi legile și poruncile Mele, pe care vi le-am dat, și dacă vă veți duce să slujiți altor dumnezei și să vă închinați înaintea lor,", "vă voi smulge din țara Mea, pe care v-am dat-o, voi lepăda de la Mine Casa aceasta, pe care am închinat-o Numelui Meu, și o voi face de pomină și de batjocură printre toate popoarele.", "Și, cât de înaltă este Casa aceasta, oricine va trece pe lângă ea va rămâne încremenit și va zice: „Pentru ce a făcut DOMNUL așa țării și Casei acesteia?”", "Și se va răspunde: „Pentru că au părăsit pe DOMNUL Dumnezeul părinților lor care i-a scos din țara Egiptului, pentru că s-au alipit de alți dumnezei, s-au închinat înaintea lor și le-au slujit; iată de ce a trimis peste ei toate aceste rele.”"],
    8: ["După douăzeci de ani, în timpul cărora Solomon a zidit Casa DOMNULUI și casa lui însuși,", "a zidit cetățile pe care i le-a dat Hiram și a așezat în ele pe copiii lui Israel.", "Solomon a mers împotriva Hamatului, la Țoba, și a pus stăpânire pe ea.", "A întărit Tadmorul, în pustiu, și toate cetățile care slujeau ca cetăți pentru merinde în Hamat.", "A întărit apoi Bet-Horonul de sus și Bet-Horonul de jos, ca cetăți întărite cu ziduri, porți și zăvoare;", "Baalatul și toate cetățile care slujeau ca cetăți pentru merinde și care țineau de el, toate cetățile pentru carele lui, cetățile pentru călăreții lui și tot ce a găsit cu cale Solomon să zidească la Ierusalim, la Liban și în toată țara al cărei stăpân era.", "Pe tot poporul care mai rămăsese din hetiți, din amoriți, din fereziți, din heviți și din iebusiți, care nu făcea parte din Israel,", "pe urmașii lor care rămăseseră după ei în țară și pe care nu-i nimiciseră copiii lui Israel, Solomon i-a ridicat ca oameni de corvoadă, ceea ce au fost până în ziua de azi.", "Solomon n-a întrebuințat ca robi, pentru lucrările lui, pe niciunul din copiii lui Israel; căci ei erau oameni de război, căpeteniile lui, slujbașii lui, mai marii carelor și călărimii lui.", "Căpeteniile puse de împăratul Solomon în fruntea poporului și însărcinați să privegheze peste el erau în număr de două sute cincizeci.", "Solomon a suit pe fata lui faraon din cetatea lui David în casa pe care i-o zidise; căci a zis: „Nevasta mea să nu locuiască în casa lui David, împăratul lui Israel, pentru că locurile în care a intrat chivotul DOMNULUI sunt sfinte.”", "Atunci Solomon a adus arderi de tot DOMNULUI pe altarul DOMNULUI, pe care-l zidise înaintea pridvorului.", "Aducea ce era poruncit de Moise pentru fiecare zi, pentru zilele de Sabat, pentru zilele de lună nouă și pentru sărbători, de trei ori pe an, la sărbătoarea Azimelor, la sărbătoarea Săptămânilor și la sărbătoarea Corturilor.", "A pus în slujbele lor, așa cum le rânduise tatăl său, David, cetele preoților, după slujba lor, pe leviți, după însărcinarea lor, care era să mărească pe DOMNUL și să facă zi de zi de slujbă în fața preoților, și pe ușieri, împărțiți la fiecare ușă, după cetele lor: căci așa poruncise David, omul lui Dumnezeu.", "Nu s-au abătut de la porunca împăratului cu privire la preoți și leviți, nici cu privire la vreun alt lucru, nici în privința vistieriilor.", "Așa s-a înfăptuit toată lucrarea lui Solomon, din ziua când s-a pus temelia Casei DOMNULUI și până în ziua când a fost isprăvită. Casa DOMNULUI a fost deci isprăvită.", "Solomon a plecat atunci la Ețion-Gheber și la Elot, pe țărmul mării, în țara Edomului.", "Și Hiram i-a trimis, prin slujitorii săi, corăbii și slujitori care cunoșteau marea. Ei s-au dus cu slujitorii lui Solomon la Ofir și au luat de acolo patru sute cincizeci de talanți de aur, pe care i-au adus împăratului Solomon."],
    9: ["Împărăteasa din Seba a auzit de faima lui Solomon și a venit la Ierusalim ca să-l încerce prin întrebări grele. Ea avea un alai foarte mare și cămile încărcate cu mirodenii, aur mult de tot și pietre scumpe. S-a dus la Solomon și i-a spus tot ce avea pe inimă.", "Solomon i-a răspuns la toate întrebările. Nu era nimic ascuns lui Solomon pe care să nu i-l spună.", "Împărăteasa din Seba a văzut înțelepciunea lui Solomon și casa pe care o zidise,", "și bucatele de la masa lui, și locuința slujitorilor lui, și slujbele și hainele celor ce-i slujeau, și paharnicii lui și hainele lor, și treptele pe care se suia la Casa DOMNULUI. Nu mai avea duh în ea.", "ea a zis împăratului: „Era adevărat deci ce am auzit eu în țara mea despre faptele și înțelepciunea ta!”", "Nu credeam tot ce se zicea, până n-am venit și am văzut cu ochii mei. Și iată că nu mi s-a istorisit nici jumătate din mărirea și înțelepciunea ta. Tu întreci faima pe care am auzit-o despre tine.", "Ferice de oamenii tăi, ferice de slujitorii tăi, care sunt pururi înaintea ta și care aud înțelepciunea ta!", "„Binecuvântat să fie DOMNUL Dumnezeul tău care a găsit plăcere în tine și te-a pus pe scaunul Lui de domnie ca împărat pentru DOMNUL Dumnezeul tău! Pentru că Dumnezeul tău iubește pe Israel și vrea să-l facă să rămână în picioare pe vecie, pentru aceea te-a pus împărat peste el, ca să faci judecată și dreptate.”", "Ea a dat împăratului o sută douăzeci de talanți de aur, foarte multe mirodenii și pietre scumpe. N-au mai fost mirodenii ca cele date împăratului Solomon de împărăteasa din Seba.", "Slujitorii lui Hiram și slujitorii lui Solomon, care au adus aur din Ofir, au adus și lemn de algum și pietre scumpe.", "Împăratul a făcut cu lemnul de algum scări pentru Casa DOMNULUI și pentru casa împăratului și harpe și lăute pentru cântăreți. Nu se mai văzuse așa ceva în țara lui Iuda.", "Împăratul Solomon a dat împărătesei din Seba tot ce a dorit ea, ce a cerut, mai mult decât adusese ea împăratului. Apoi s-a întors și s-a dus în țara ei, ea și slujitorii ei.", "Greutatea aurului care venea pe fiecare an lui Solomon era de șase sute șaizeci și șase de talanți de aur,", "afară de ce lua de la negustorii cei mari și de la cei mici, de la toți împărații Arabiei și de la dregătorii țării, care aduceau aur și argint lui Solomon.", "Împăratul Solomon a făcut două sute de scuturi mari de aur bătut, și pentru fiecare din ele a întrebuințat șase sute de sicli de aur bătut,", "și alte trei sute de scuturi de aur bătut, și pentru fiecare din ele a întrebuințat trei sute de sicli de aur; și împăratul le-a pus în casa Pădurii Libanului.", "Împăratul a făcut un mare scaun de domnie de fildeș și l-a acoperit cu aur curat.", "Scaunul acesta de domnie avea șase trepte și un așternut pentru picioare de aur, care se ținea de scaunul de domnie; de fiecare parte a scaunului erau rezemători, lângă rezemători erau doi lei,", "și pe cele șase trepte, de o parte și de alta, erau doisprezece lei. Așa ceva nu s-a făcut pentru nicio împărăție.", "Toate paharele împăratului Solomon erau de aur și toate vasele din casa Pădurii Libanului erau de aur curat. Nu era nimic de argint: argintului nu i se dădea niciun preț pe vremea lui Solomon.", "Căci împăratul avea corăbii din Tarsis care călătoreau cu slujitorii lui Hiram; și, la fiecare trei ani, veneau corăbiile din Tarsis, aducând aur și argint, fildeș, maimuțe și păuni.", "Împăratul Solomon a întrecut pe toți împărații pământului prin bogățiile și înțelepciunea lui.", "Toți împărații pământului căutau să vadă pe Solomon, ca să audă înțelepciunea pe care o pusese Dumnezeu în inima lui.", "Și fiecare din ei își aducea darul lui, lucruri de argint și lucruri de aur, haine, arme, mirodenii, cai și catâri; așa era în fiecare an.", "Solomon avea patru mii de iesle pentru caii de la carele lui și douăsprezece mii de călăreți, pe care i-a așezat în cetățile unde își ținea carele și la Ierusalim lângă împărat.", "El stăpânea peste toți împărații, de la Râu până la țara filistenilor și până la hotarul Egiptului.", "Împăratul a făcut argintul tot așa de obișnuit la Ierusalim ca pietrele, și cedrii, tot atât de mulți ca smochinii sălbatici care cresc pe câmpie.", "Din Egipt și din toate țările se aduceau cai pentru Solomon.", "Celelalte fapte ale lui Solomon, cele dintâi și cele de pe urmă, nu sunt scrise oare în cartea prorocului Natan, în prorocia lui Ahia din Silo și în descoperirile prorocului Ieedo despre Ieroboam, fiul lui Nebat?", "Solomon a domnit patruzeci de ani la Ierusalim peste tot Israelul.", "Apoi Solomon a adormit cu părinții lui, și l-au îngropat în cetatea tatălui său, David. Și, în locul lui, a domnit fiul său Roboam."],
    10: ["Roboam s-a dus la Sihem, căci tot Israelul venise la Sihem să-l facă împărat.", "Când a auzit lucrul acesta, Ieroboam, fiul lui Nebat, era în Egipt, unde fugise de împăratul Solomon; și s-a întors din Egipt.", "Au trimis să-l cheme. Atunci Ieroboam și tot Israelul au venit la Roboam și i-au vorbit așa:", "„Tatăl tău ne-a îngreuiat jugul: acum ușurează această aspră robie și jugul greu pe care l-a pus peste noi tatăl tău. Și îți vom sluji.”", "El le-a zis: „Întoarceți-vă la mine după trei zile.” Și poporul a plecat.", "Împăratul Roboam a întrebat pe bătrânii care fuseseră cu tatăl său, Solomon, în timpul vieții lui, și a zis: „Ce mă sfătuiți să răspund poporului acestuia?”", "Și iată ce i-au zis ei: „Dacă vei fi bun cu poporul acesta, dacă-i vei primi bine și dacă le vei vorbi cu bunăvoință, îți vor sluji pe vecie.”", "Dar Roboam a lăsat sfatul pe care i-l dădeau bătrânii și a întrebat pe tinerii care crescuseră cu el și care-l înconjurau.", "El le-a zis: „Ce mă sfătuiți să răspund poporului acestuia care-mi vorbește astfel: «Ușurează jugul pe care l-a pus tatăl tău peste noi»?”", "Și iată ce i-au zis tinerii care crescuseră cu el: „Așa să vorbești poporului acestuia care ți-a vorbit așa: «Tatăl tău ne-a îngreuiat jugul, iar tu ușurează-ni-l!», să le vorbești așa: «Degetul meu cel mic este mai gros decât coapsele tatălui meu.»”", "„Acum, tatăl meu a pus peste voi un jug greu, dar eu îl voi face și mai greu: tatăl meu v-a pedepsit cu bice, dar eu vă voi pedepsi cu scorpioni.”", "Ieroboam și tot poporul au venit la Roboam a treia zi, după cum le spusese împăratul: „Întoarceți-vă la mine peste trei zile.”", "Împăratul le-a răspuns aspru. Împăratul Roboam a lăsat sfatul bătrânilor.", "și le-a vorbit așa, după sfatul tinerilor: „Tatăl meu v-a îngreuiat jugul, dar eu îl voi îngreuia și mai mult; tatăl meu v-a pedepsit cu bice, dar eu vă voi pedepsi cu scorpioni.”", "Astfel împăratul n-a ascultat pe popor; căci așa rânduise Dumnezeu, în vederea împlinirii cuvântului pe care-l spusese DOMNUL prin Ahia din Silo lui Ieroboam, fiul lui Nebat.", "Când a văzut tot Israelul că împăratul nu-l ascultă, poporul a răspuns împăratului: „Ce parte avem noi cu David? Noi n-avem nicio moștenire cu fiul lui Isai! La corturile tale, Israele! Acum, vezi-ți de casă, Davide!” Atunci tot Israelul a plecat la corturile lui.", "Copiii lui Israel care locuiau în cetățile lui Iuda au fost singurii peste care a domnit Roboam.", "Atunci, împăratul Roboam a trimis pe Hadoram, care era mai mare peste dări. Hadoram a fost împroșcat cu pietre de copiii lui Israel și a murit. Și împăratul Roboam s-a grăbit și s-a suit într-un car ca să fugă la Ierusalim.", "„Astfel s-a dezlipit Israel de casa lui David până în ziua de azi.”"],
    11: ["Roboam, venind la Ierusalim, a strâns casa lui Iuda și a lui Beniamin, o sută optzeci de mii de oameni de frunte, buni pentru război, ca să lupte împotriva lui Israel și să-l aducă iarăși sub stăpânirea lui Roboam.", "Dar cuvântul DOMNULUI a vorbit astfel lui Șemaia, omul lui Dumnezeu:", "„Vorbește lui Roboam, fiul lui Solomon, împăratul lui Iuda, și întregului Israel din Iuda și din Beniamin. Și spune-le:”", "„Așa vorbește DOMNUL: «Să nu vă suiți și să nu faceți război împotriva fraților voștri! Fiecare să se întoarcă acasă, căci de la Mine s-a întâmplat lucrul acesta.»” Ei au ascultat cuvintele DOMNULUI și s-au întors, fără să mai meargă împotriva lui Ieroboam.", "Roboam a locuit la Ierusalim și a zidit cetăți întărite în Iuda.", "A zidit Betleemul, Etamul, Tecoa,", "Bet-Țur, Soco, Adulam,", "Gat, Mareșa, Zif,", "Adoraim, Lachis, Azeca,", "Țorea, Aialon și Hebronul, care erau în Iuda și în Beniamin și erau cetăți întărite.", "Le-a întărit, a pus în ele căpitani și magazii de bucate, de untdelemn și vin.", "A pus în fiecare din aceste cetăți scuturi și sulițe, și le-a făcut foarte tari. Iuda și Beniamin erau ai lui.", "Preoții și leviții care se aflau în tot Israelul au ținut cu el din tot ținutul lor;", "căci leviții și-au părăsit ținuturile și moșiile și au venit în Iuda și la Ierusalim, pentru că Ieroboam și fiii săi i-au împiedicat să-și împlinească slujbele ca preoți ai DOMNULUI.", "Ieroboam a pus preoți pentru înălțimi, pentru idolii în chip de țapi și viței pe care îi făcuse.", "Aceia din toate semințiile lui Israel care aveau pe inimă să caute pe DOMNUL Dumnezeul lui Israel au urmat pe leviți la Ierusalim, ca să jertfească DOMNULUI Dumnezeului părinților lor.", "Ei au dat astfel tărie împărăției lui Iuda și au întărit pe Roboam, fiul lui Solomon, timp de trei ani; căci trei ani au umblat în calea lui David și a lui Solomon.", "Roboam a luat de nevastă pe Mahalat, fata lui Ierimot, fiul lui David și al Abihailei, fata lui Eliab, fiul lui Isai.", "Ea i-a născut fii pe: Ieuș, Șemaria și Zaham.", "După ea, a luat pe Maaca, fata lui Absalom. Ea i-a născut pe Abia, pe Atai, pe Ziza și pe Șelomit.", "Roboam iubea pe Maaca, fata lui Absalom, mai mult decât pe toate nevestele și țiitoarele lui; căci a avut optsprezece neveste și șaizeci de țiitoare și a născut douăzeci și opt de fii și șaizeci de fete.", "Roboam a dat cel dintâi loc lui Abia, fiul Maacăi, și l-a pus căpetenie peste frații lui, căci voia să-l facă împărat.", "El a lucrat cu minte, împrăștiind pe toți fiii săi în toate ținuturile lui Iuda și lui Beniamin, în toate cetățile întărite; le-a dat de mâncare din belșug și le-a căutat o mulțime de neveste."],
    12: ["Când s-a întărit Roboam în domnie și a căpătat putere, a părăsit Legea DOMNULUI, și tot Israelul a părăsit-o împreună cu el.", "În al cincilea an al domniei lui Roboam, Șișac, împăratul Egiptului, s-a suit împotriva Ierusalimului, pentru că păcătuiseră împotriva DOMNULUI.", "Avea o mie două sute de care și șaizeci de mii de călăreți; și împreună cu el a venit din Egipt un popor fără număr, dintre libieni, suchieni și etiopieni.", "A luat cetățile întărite ale lui Iuda și a ajuns până la Ierusalim.", "Atunci prorocul Șemaia s-a dus la Roboam și la căpeteniile lui Iuda, care se adunaseră în Ierusalim, la apropierea lui Șișac, și le-a zis: „Așa vorbește DOMNUL: «Voi M-ați părăsit; vă părăsesc și Eu și vă dau în mâinile lui Șișac.»”", "Căpeteniile lui Israel și împăratul s-au smerit și au zis: „DOMNUL este drept!”", "Și, când a văzut DOMNUL că s-au smerit, cuvântul DOMNULUI a vorbit astfel lui Șemaia: „S-au smerit, nu-i voi nimici, le voi da puțină izbăvire și mânia Mea nu va veni asupra Ierusalimului prin Șișac;”", "„dar îi vor fi supuși și vor ști ce înseamnă să-Mi slujească Mie sau să slujească împărățiilor altor țări.”", "Șișac, împăratul Egiptului, s-a suit împotriva Ierusalimului. A luat vistieriile Casei DOMNULUI și vistieriile casei împăratului, a luat tot. A luat scuturile de aur pe care le făcuse Solomon.", "Împăratul Roboam a făcut în locul lor niște scuturi de aramă și le-a dat în grija căpeteniilor alergătorilor, care păzeau intrarea casei împăratului.", "Ori de câte ori se ducea împăratul la Casa DOMNULUI, alergătorii veneau și le purtau înaintea lui; apoi le aduceau iarăși în odaia alergătorilor.", "Pentru că Roboam se smerise, DOMNUL Și-a abătut mânia de la el și nu l-a nimicit de tot. Și tot mai era ceva bun în Iuda.", "Împăratul Roboam s-a întărit în Ierusalim și a domnit. Avea patruzeci și unu de ani când a ajuns împărat și a domnit șaptesprezece ani la Ierusalim, cetatea pe care o alesese DOMNUL din toate semințiile lui Israel, ca să-Și pună Numele în ea. Mama sa se numea Naama, amonita.", "El a făcut lucruri rele, pentru că nu și-a pus inima să caute pe DOMNUL.", "Faptele lui Roboam, cele dintâi și cele de pe urmă, nu sunt scrise oare în cartea prorocului Șemaia și a prorocului Ido, în cărțile spițelor de neam? Totdeauna a fost război între Roboam și Ieroboam.", "„Roboam a adormit cu părinții săi și a fost îngropat în cetatea lui David. Și, în locul lui, a domnit fiul său Abia.”"],
    13: ["În al optsprezecelea an al domniei lui Ieroboam, peste Iuda a început să domnească Abia.", "El a domnit trei ani la Ierusalim. Mama sa se numea Micaia, fata lui Uriel din Ghibeea. Între Abia și Ieroboam a fost război.", "Abia a început lupta cu o oaste de războinici viteji, patru sute de mii de oameni aleși; și Ieroboam s-a înșiruit de bătaie împotriva lui cu opt sute de mii de oameni aleși, războinici viteji.", "De pe vârful muntelui Țemaraim, care face parte din muntele lui Efraim, Abia s-a sculat și a zis: „Ascultă-mă, Ieroboame, și tot Israelul!”", "Nu trebuie oare să știți că DOMNUL Dumnezeul lui Israel a dat pe vecie domnia peste Israel lui David și fiilor lui printr-un legământ de sare?", "Dar Ieroboam, fiul lui Nebat, slujitorul lui Solomon, fiul lui David, s-a sculat și s-a răzvrătit împotriva stăpânului său.", "Niște oameni de nimic, oameni răi, s-au strâns la el și s-au împotrivit lui Roboam, fiul lui Solomon. Roboam era tânăr și plăpând la inimă și nu putea să li se împotrivească.", "Și acum, voi credeți că puteți ieși biruitori asupra împărăției DOMNULUI, care este în mâinile fiilor lui David; și voi sunteți o mare mulțime și aveți cu voi vițeii de aur pe care vi i-a făcut Ieroboam ca dumnezei.", "N-ați îndepărtat voi pe preoții DOMNULUI, pe fiii lui Aaron și pe leviți, și nu v-ați făcut voi preoți, ca și popoarele celorlalte țări? Oricine vine să se consacre cu un vițel și șapte berbeci poate deveni preot al unor dumnezei care nu sunt dumnezei.", "Dar cât despre noi, DOMNUL este Dumnezeul nostru, și noi nu L-am părăsit. Preoții din slujba DOMNULUI sunt fiii lui Aaron, iar leviții stau și își împlinesc slujbele.", "Noi aducem în fiecare dimineață și în fiecare seară arderi de tot DOMNULUI, ardem tămâie mirositoare, punem pâinile pentru punerea înaintea DOMNULUI pe masa cea curată și aprindem în fiecare seară sfeșnicul de aur cu candelele lui; căci păzim poruncile DOMNULUI Dumnezeului nostru. Dar voi L-ați părăsit.", "„Iată că Dumnezeu și preoții Lui sunt cu noi, în fruntea noastră, și avem și trâmbițele răsunătoare ca să sunăm din ele împotriva voastră. Copii ai lui Israel, nu faceți război împotriva DOMNULUI Dumnezeului părinților voștri, căci nu veți avea nicio izbândă!”", "Ieroboam i-a luat pe dinapoi, cu ajutorul unor oameni puși la pândă, așa că oștile lui erau în fața lui Iuda, iar cei ce stăteau la pândă erau înapoia lor.", "Cei din Iuda, întorcându-se, au avut de luptat înainte și înapoi. Au strigat către DOMNUL, și preoții au sunat din trâmbițe.", "Oamenii lui Iuda au scos un strigăt de război și, la strigătul de război al oamenilor lui Iuda, DOMNUL a lovit pe Ieroboam și pe tot Israelul dinaintea lui Abia și a lui Iuda.", "Copiii lui Israel au fugit dinaintea lui Iuda, și Dumnezeu i-a dat în mâinile lui.", "Abia și poporul lui le-au pricinuit o mare înfrângere, și cinci sute de mii de oameni aleși au căzut morți printre cei din Israel.", "Copiii lui Israel au fost smeriți în vremea aceea, și copiii lui Iuda au câștigat biruința, pentru că se sprijiniseră pe DOMNUL Dumnezeul părinților lor.", "Abia a urmărit pe Ieroboam și i-a luat cetăți: Betelul cu satele lui, Ieșana cu satele ei și Efronul cu satele lui.", "Ieroboam n-a mai avut putere pe vremea lui Abia, și DOMNUL l-a lovit, și a murit.", "Dar Abia a ajuns puternic; a avut paisprezece neveste și a născut douăzeci și doi de fii și șaisprezece fete.", "Celelalte fapte ale lui Abia, ce a făcut și ce a spus el, sunt scrise în cartea prorocului Ido."],
    14: ["Abia a adormit cu părinții lui și a fost îngropat în cetatea lui David. Și, în locul lui, a domnit fiul său Asa. Pe vremea lui, țara a avut odihnă zece ani.", "Asa a făcut ce este bine și plăcut înaintea DOMNULUI Dumnezeului său.", "A îndepărtat altarele dumnezeilor străini și înălțimile, a sfărâmat stâlpii și a tăiat stâlpii Așerei.", "A poruncit lui Iuda să caute pe DOMNUL Dumnezeul părinților săi și să împlinească Legea și poruncile.", "A îndepărtat din toate cetățile lui Iuda înălțimile și stâlpii închinați soarelui. Și împărăția a avut pace sub el.", "A zidit cetăți întărite în Iuda; căci țara a fost liniștită, și împotriva lui n-a fost război în anii aceia, pentru că DOMNUL i-a dat odihnă.", "El a zis lui Iuda: „Să zidim aceste cetăți și să le înconjurăm cu ziduri, cu turnuri, cu porți și cu zăvoare; țara este încă a noastră, căci am căutat pe DOMNUL Dumnezeul nostru. L-am căutat, și El ne-a dat odihnă din toate părțile.” Astfel au zidit și au izbutit.", "Asa avea o oștire de trei sute de mii de oameni din Iuda, care purtau scut și suliță, și două sute optzeci de mii din Beniamin, care purtau scut și trăgeau cu arcul, toți oamenii viteji.", "Zerah, etiopianul, a ieșit împotriva lor cu o oștire de un milion de oameni și trei sute de care și a înaintat până la Mareșa.", "Asa a mers înaintea lui, și s-au înșiruit de bătaie în valea Țefata, lângă Mareșa.", "Asa a chemat pe DOMNUL Dumnezeul lui și a zis: „DOAMNE, numai Tu poți veni în ajutor celui slab ca și celui tare: vino în ajutorul nostru, DOAMNE Dumnezeul nostru! Căci pe Tine ne sprijinim și în Numele Tău am venit împotriva acestei mulțimi. DOAMNE, Tu ești Dumnezeul nostru: să nu iasă biruitor omul împotriva Ta!”", "DOMNUL a lovit pe etiopieni dinaintea lui Asa și dinaintea lui Iuda, și etiopienii au luat-o la fugă.", "Asa și poporul care era cu el i-a urmărit până la Gherar, și etiopienii au căzut fără să-și poată scăpa viața, căci au fost zdrobiți înaintea DOMNULUI și înaintea oștirii Lui. Oastea lui Iuda a luat o pradă foarte mare;", "au bătut toate cetățile din împrejurimile Gherarului, căci groaza DOMNULUI căzuse peste ele, și au jefuit toate cetățile, a căror pradă era mare.", "Au lovit și corturile turmelor și au luat cu ei o mare mulțime de oi și de cămile. Apoi s-au întors la Ierusalim."],
    15: ["Duhul lui Dumnezeu a venit peste Azaria, fiul lui Oded,", "și Azaria s-a dus înaintea lui Asa și i-a zis: „Ascultați-mă, Asa și tot Iuda și Beniamin! DOMNUL este cu voi când sunteți cu El; dacă-L căutați, Îl veți găsi; iar dacă-L părăsiți, și El vă va părăsi.”", "Multă vreme Israel a fost fără Dumnezeul cel adevărat, fără preot care să învețe pe oameni și fără Lege.", "Dar în mijlocul strâmtorării lor s-au întors la DOMNUL Dumnezeul lui Israel, L-au căutat și L-au găsit.", "În vremurile acelea nu era liniște pentru cei ce se duceau și veneau, căci erau mari tulburări printre toți locuitorii țării;", "un popor se bătea împotriva altui popor, o cetate, împotriva altei cetăți, pentru că Dumnezeu le tulbura cu tot felul de strâmtorări:", "„voi, dar, întăriți-vă și nu lăsați să vă slăbească mâinile, căci faptele voastre vor avea o răsplată.”", "După ce a auzit aceste cuvinte și prorocia lui Oded, prorocul, Asa s-a întărit și a îndepărtat urâciunile din toată țara lui Iuda și Beniamin și din cetățile pe care le luase pe muntele lui Efraim și a înnoit altarul DOMNULUI care era înaintea pridvorului DOMNULUI.", "A strâns pe tot Iuda și Beniamin și pe cei din Efraim, din Manase și din Simeon care locuiau printre ei, căci un mare număr dintre oamenii lui Israel au trecut la el când au văzut că DOMNUL Dumnezeul lui era cu el.", "S-au adunat la Ierusalim în luna a treia a anului al cincisprezecelea al domniei lui Asa. În ziua aceasta,", "au jertfit DOMNULUI din prada pe care o aduseseră: șapte sute de boi și șapte mii de oi.", "Au făcut legământ să caute pe DOMNUL Dumnezeul părinților lor din toată inima și din tot sufletul lor;", "și oricine nu căuta pe DOMNUL Dumnezeul lui Israel trebuia omorât, fie mic fie mare, fie bărbat, fie femeie.", "Au jurat credință DOMNULUI cu glas tare, cu strigăte de bucurie și cu sunet de trâmbițe și de buciume;", "tot Iuda s-a bucurat de jurământul acesta, căci juraseră din toată inima lor, căutaseră pe DOMNUL din toată dorința lor și-L găsiseră. Și DOMNUL le-a dat odihnă de jur împrejur.", "Împăratul Asa n-a lăsat nici chiar pe mama sa, Maaca, să mai fie împărăteasă, pentru că făcuse un chip cioplit al Așerei. Asa i-a dărâmat chipul, l-a făcut praf și l-a ars lângă pârâul Chedron.", "Dar înălțimile tot n-au fost îndepărtate din Israel, măcar că inima lui Asa a fost în totul a DOMNULUI în tot timpul vieții lui.", "A pus în Casa lui Dumnezeu lucrurile închinate DOMNULUI de tatăl său și de el însuși: argint, aur și vase.", "N-a fost niciun război până la al treizeci și cincilea an al domniei lui Asa."],
    16: ["În al treizeci și șaselea an al domniei lui Asa, Baeșa, împăratul lui Israel, s-a suit împotriva lui Iuda; și a întărit Rama, ca să nu lase pe ai lui Asa, împăratul lui Iuda, să iasă și să intre.", "Asa a scos argint și aur din vistieriile Casei DOMNULUI și ale casei împăratului și a trimis soli la Ben-Hadad, împăratul Siriei, care locuia la Damasc. Și a pus să-i spună:", "„Să fie un legământ între mine și tine, cum a fost unul între tatăl meu și tatăl tău. Iată, îți trimit argint și aur. Du-te și rupe legământul tău cu Baeșa, împăratul lui Israel, ca să se depărteze de la mine.”", "Ben-Hadad a ascultat pe împăratul Asa; a trimis pe căpeteniile oștirii sale împotriva cetăților lui Israel și au bătut Iionul, Dan, Abel-Maim și toate locurile pentru merinde din cetățile lui Neftali.", "Când a auzit Baeșa, a încetat să mai întărească Rama și a pus capăt lucrărilor sale.", "Împăratul Asa a pus pe tot Iuda să ridice pietrele și lemnele pe care le întrebuința Baeșa la întărirea Ramei și le-a întrebuințat la întărirea Ghebei și Mițpei.", "În vremea aceea, Hanani, văzătorul, s-a dus la Asa, împăratul lui Iuda, și i-a zis: „Pentru că te-ai sprijinit pe împăratul Siriei, și nu te-ai sprijinit pe DOMNUL Dumnezeul tău, de aceea a scăpat oastea împăratului Siriei din mâinile tale.”", "Etiopienii și libienii nu alcătuiau oare o oaste mare, cu o mulțime de care și călăreți? Și totuși DOMNUL i-a dat în mâinile tale, pentru că te sprijiniseși pe El.", "„Căci DOMNUL Își întinde privirile peste tot pământul, ca să sprijine pe aceia a căror inimă este întreagă a Lui. Ai lucrat ca un nebun în privința aceasta, căci de acum vei avea războaie.”", "Asa s-a mâniat pe văzător și l-a pus la închisoare, pentru că era înfuriat împotriva lui. Tot în același timp, Asa a apăsat și pe unii din popor.", "Faptele lui Asa, cele dintâi și cele de pe urmă, sunt scrise în cartea împăraților lui Iuda și Israel.", "În al treizeci și nouălea an al domniei sale, Asa s-a îmbolnăvit de picioare așa încât avea mari dureri; chiar în timpul bolii lui, n-a căutat pe DOMNUL, ci a întrebat pe doctori.", "Asa a adormit cu părinții săi și a murit în al patruzeci și unulea an al domniei lui;", "l-au îngropat în mormântul pe care și-l săpase în cetatea lui David. L-au culcat pe un pat pe care-l umpluseră cu mirodenii și mirosuri pregătite după meșteșugul celui ce pregătește mirul și au făcut pentru el un foc foarte mare."],
    17: ["În locul lui, a domnit fiul său Iosafat. El s-a întărit împotriva lui Israel:", "a pus oști în toate cetățile întărite ale lui Iuda și a rânduit căpetenii în țara lui Iuda și în cetățile lui Efraim pe care le luase tatăl său, Asa.", "DOMNUL a fost cu Iosafat, pentru că a umblat în cele dintâi căi ale tatălui său David și n-a căutat pe Baali;", "căci a alergat la Dumnezeul tatălui său și a urmat poruncile Lui, fără să facă ce făcea Israel.", "DOMNUL a întărit domnia în mâinile lui Iosafat, căruia tot Iuda îi aducea daruri. Și a avut o mulțime de bogății și slavă.", "Inima lui s-a înălțat în căile DOMNULUI, și a îndepărtat din Iuda chiar și înălțimile și stâlpii Așerei.", "În al treilea an al domniei lui, a însărcinat pe căpeteniile sale: Ben-Hail, Obadia, Zaharia, Netaneel și Mica, să se ducă să învețe pe oameni în cetățile lui Iuda.", "A trimis cu ei pe leviții: Șemaia, Netania, Zebadia, Asael, Șemiramot, Ionatan, Adonia, Tobia și Tob-Adonia, leviți, și pe preoții Elișama și Ioram.", "Ei au învățat pe oameni în Iuda, având cu ei cartea Legii DOMNULUI. Au străbătut toate cetățile lui Iuda și au învățat pe oameni în mijlocul poporului.", "Groaza DOMNULUI a apucat toate împărățiile țărilor dimprejurul lui Iuda, și n-au făcut război împotriva lui Iosafat.", "Niște filisteni au adus lui Iosafat daruri și un bir în argint; și arabii i-au adus și ei turme, șapte mii șapte sute de berbeci și șapte mii șapte sute de țapi.", "Iosafat se ridicase la cea mai înaltă treaptă de mărire. A zidit în Iuda cetățui și cetăți pentru merinde.", "A avut multe lucrări în cetățile lui Iuda și avea la Ierusalim o ceată de oameni viteji ca ostași.", "Iată numărul lor, după casele părinților lor: Din Iuda, căpetenii peste o mie: Adna, căpetenia, cu trei sute de mii de viteji;", "după el, Iohanan, căpetenia, cu două sute optzeci de mii de oameni;", "după el, Amasia, fiul lui Zicri, care se dăruise de bunăvoie DOMNULUI, cu două sute de mii de viteji.", "Din Beniamin: Eliada, om viteaz, cu două sute de mii de oameni înarmați cu arc și cu scut,", "și după el, Zozabad, cu o sută optzeci de mii de oameni înarmați pentru război.", "Aceștia sunt cei ce erau în slujba împăratului, afară de aceia pe care îi pusese împăratul în toate cetățile întărite ale lui Iuda."],
    18: ["Iosafat a avut bogății și slavă din belșug și s-a încuscrit cu Ahab.", "După câțiva ani s-a coborât la Ahab în Samaria. Ahab a tăiat, pentru el și pentru poporul care era cu el, un mare număr de oi și boi și l-a rugat să se suie la Ramot din Galaad.", "Ahab, împăratul lui Israel, a zis lui Iosafat, împăratul lui Iuda: „Vrei să vii cu mine la Ramot în Galaad?” Iosafat i-a răspuns: „Eu ca tine, și poporul meu ca poporul tău, vom merge la luptă împotriva lui cu tine.”", "Apoi Iosafat a zis împăratului lui Israel: „Întreabă acum, te rog, cuvântul DOMNULUI.”", "Împăratul lui Israel a strâns pe proroci, în număr de patru sute, și le-a zis: „Să ne ducem la luptă împotriva Ramotului din Galaad sau să-mi văd de treabă?” Și ei au răspuns: „Suie-te, și Dumnezeu o va da în mâinile împăratului.”", "Dar Iosafat a zis: „Nu mai este aici niciun proroc al DOMNULUI prin care să-L putem întreba?”", "Împăratul lui Israel a răspuns lui Iosafat: „Mai este un om prin care am putea să întrebăm pe DOMNUL; dar îl urăsc, căci nu-mi prorocește nimic bun, nu prorocește niciodată decât rău: este Mica, fiul lui Imla.” Și Iosafat a zis: „Să nu vorbească așa împăratul!”", "Atunci împăratul lui Israel a chemat un dregător și i-a zis: „Trimite să vină îndată Mica, fiul lui Imla.”", "Împăratul lui Israel și Iosafat, împăratul lui Iuda, ședeau fiecare pe scaunul lui de domnie, îmbrăcați cu hainele lor împărătești; ședeau în locul de la intrarea porții Samariei. Și toți prorocii proroceau înaintea lor.", "Zedechia, fiul lui Chenaana, își făcuse niște coarne de fier și a zis: „Așa vorbește DOMNUL: «Cu aceste coarne vei bate pe sirieni până îi vei nimici.»”", "Și toți prorocii au prorocit la fel, zicând: „Suie-te la Ramot în Galaad, căci vei avea izbândă, și DOMNUL o va da în mâinile împăratului.”", "Solul care se dusese să cheme pe Mica i-a vorbit așa: „Iată, prorocii cu un gând prorocesc de bine împăratului; cuvântul tău să fie, dar, ca și cuvântul fiecăruia din ei! Vestește de bine!”", "Mica a răspuns: „Viu este DOMNUL că voi vesti ce va spune Dumnezeul meu.”", "Când a venit la împărat, împăratul i-a zis: „Mica, să ne ducem la luptă împotriva Ramotului din Galaad sau să-mi văd de treabă?” El a răspuns: „Suiți-vă! Căci veți avea izbândă, și vor fi dați în mâinile voastre.”", "Și împăratul i-a zis: „De câte ori va trebui să te pun să juri că nu-mi vei spune decât adevărul în Numele DOMNULUI?”", "Mica a răspuns: „Văd tot Israelul risipit pe munți ca niște oi care n-au păstor; și DOMNUL a zis: «Oamenii aceștia n-au stăpân, fiecare să se întoarcă în pace acasă!»”", "Împăratul lui Israel a zis lui Iosafat: „Nu ți-am spus eu? El nu-mi prorocește nimic bun, nu-mi prorocește decât rău.”", "Și Mica a zis: „Ascultați, dar, cuvântul DOMNULUI! Am văzut pe DOMNUL stând pe scaunul Său de domnie, și toată oastea cerurilor stând la dreapta și la stânga Lui.”", "Și DOMNUL a zis: „Cine va amăgi pe Ahab, împăratul lui Israel, ca să se suie la Ramot în Galaad și să piară acolo?” Unul a răspuns într-un fel, iar altul în alt fel.", "Și un duh a venit și s-a înfățișat înaintea DOMNULUI, și a zis: „Eu îl voi amăgi.” DOMNUL i-a zis: „Cum?”", "„Voi ieși”, a răspuns el, „și voi fi un duh de minciună în gura tuturor prorocilor lui.” DOMNUL a zis: „Îl vei amăgi și vei izbuti; ieși și fă așa.”", "„Și acum, iată că DOMNUL a pus un duh de minciună în gura prorocilor tăi care sunt de față. Dar DOMNUL a vorbit rău împotriva ta.”", "Atunci Zedechia, fiul lui Chenaana, apropiindu-se, a lovit pe Mica peste obraz și a zis: „Pe ce drum a ieșit Duhul DOMNULUI din mine ca să-ți vorbească?”", "Mica a răspuns: „Vei vedea în ziua când vei umbla din odaie în odaie ca să te ascunzi.”", "Împăratul lui Israel a zis: „Luați pe Mica și duceți-l la Amon, căpetenia cetății, și la Ioas, fiul împăratului.”", "Și spuneți: „Așa vorbește împăratul: «Băgați pe omul acesta în temniță și hrăniți-l cu pâinea și cu apa întristării, până mă voi întoarce în pace.»”", "Și Mica a zis: „Dacă te vei întoarce în pace, n-a vorbit DOMNUL prin mine!” Apoi a mai zis: „Voi, toate popoarele, auziți!”", "Împăratul lui Israel și Iosafat, împăratul lui Iuda, s-au suit la Ramot în Galaad.", "Împăratul lui Israel a zis lui Iosafat: „Vreau să-mi schimb hainele, ca să mă duc la luptă; dar tu, îmbracă-te cu hainele tale.” Împăratul lui Israel și-a schimbat hainele, iar ei au intrat în luptă.", "Împăratul Siriei dăduse următoarea poruncă mai marilor peste carele lui: „Să nu vă luptați nici cu cel mic, nici cu cel mare, ci să vă luptați numai cu împăratul lui Israel.”", "Când căpeteniile carelor l-au văzut pe Iosafat, au zis: „Este împăratul lui Israel!” L-au înconjurat ca să lupte împotriva lui, dar Iosafat a strigat, DOMNUL l-a ajutat, iar Dumnezeu i-a făcut să se îndepărteze de el.", "Mai marii carelor, văzând că nu era împăratul lui Israel, s-au depărtat de el.", "Atunci un om a tras cu arcul la întâmplare și a lovit pe împăratul lui Israel între încheieturile armăturii. Împăratul a zis celui ce-i mâna carul: „Întoarce și scoate-mă din câmpul de bătaie, căci sunt rănit.”", "Lupta a fost înverșunată în ziua aceea. Împăratul lui Israel a stat în car, în fața sirienilor, până seara, și a murit pe la apusul soarelui."],
    19: ["Iosafat, împăratul lui Iuda, s-a întors în pace acasă la Ierusalim.", "Iehu, fiul prorocului Hanani, i-a ieșit înainte și a zis împăratului Iosafat: „Cum de ai ajutat tu pe cel rău și ai iubit pe cei ce urăsc pe DOMNUL? Din pricina aceasta este mâniat DOMNUL pe tine.”", "„Dar tot se mai găsește și ceva bun în tine, căci ai înlăturat din țară Așerele și ți-ai pus inima să caute pe Dumnezeu.”", "Iosafat a rămas la Ierusalim. Apoi a mai făcut o călătorie prin mijlocul poporului, de la Beer-Șeba până la muntele lui Efraim, și i-a adus înapoi la DOMNUL Dumnezeul părinților lor.", "A pus judecători în toate cetățile întărite din țara lui Iuda, în fiecare cetate.", "Și a zis judecătorilor: „Luați seama la ce veți face, căci nu pentru oameni veți rosti judecăți; ci pentru DOMNUL, care va fi lângă voi când le veți rosti.”", "„Acum, frica DOMNULUI să fie peste voi; vegheați asupra faptelor voastre, căci la DOMNUL Dumnezeul nostru nu este nicio nelegiuire, nici nu se are în vedere fața oamenilor, nici nu se primesc daruri.”", "Când s-a întors la Ierusalim, Iosafat a pus și aici, pentru judecățile DOMNULUI și pentru neînțelegeri, leviți, preoți și căpetenii peste casele părintești ale lui Israel.", "Și iată poruncile pe care li le-a dat: „Voi să lucrați în frica DOMNULUI, cu credință și curăție de inimă.”", "În orice neînțelegere care vă va fi supusă de frații voștri care locuiesc în cetățile lor, și anume: cu privire la un omor, la o lege, la o poruncă, la învățături și rânduieli, să-i luminați, ca să nu se facă vinovați față de DOMNUL și să nu izbucnească mânia Lui peste voi și peste frații voștri. Așa să lucrați, și nu veți fi vinovați.", "„Și iată că aveți în frunte pe marele preot Amaria, pentru toate treburile DOMNULUI, și pe Zebadia, fiul lui Ismael, căpetenia casei lui Iuda, pentru toate treburile împăratului, și aveți înainte ca dregători pe leviți. Întăriți-vă și lucrați, și DOMNUL să fie cu cel ce va face binele!”"],
    20: ["După aceea, fiii lui Moab și fiii lui Amon și cu ei niște maoniți au pornit cu război împotriva lui Iosafat.", "Au venit și au dat de știre lui Iosafat, zicând: „O mare mulțime înaintează împotriva ta de dincolo de mare, din Siria, și sunt la Hațațon-Tamar, adică En-Ghedi.”", "În spaima sa, Iosafat și-a îndreptat fața să caute pe DOMNUL și a vestit un post pentru tot Iuda.", "Iuda s-a adunat să cheme pe DOMNUL și au venit din toate cetățile lui Iuda să caute pe DOMNUL.", "Iosafat a venit în mijlocul adunării lui Iuda și a Ierusalimului, în Casa DOMNULUI, înaintea curții celei noi.", "Și a zis: „DOAMNE Dumnezeul părinților noștri, nu ești Tu Dumnezeu în ceruri și nu stăpânești Tu peste toate împărățiile neamurilor? Oare n-ai Tu în mână tăria și puterea, așa că nimeni nu Ți se poate împotrivi?”", "Oare n-ai izgonit Tu, Dumnezeul nostru, pe locuitorii țării acesteia dinaintea poporului Tău, Israel, și n-ai dat-o Tu pentru totdeauna de moștenire seminței lui Avraam, prietenul Tău?", "Ei au locuit-o și Ți-au zidit în ea un Locaș Sfânt pentru Numele Tău, zicând:", "„Dacă va veni peste noi vreo nenorocire, sabia, judecata, ciuma sau foametea, ne vom înfățișa înaintea Casei acesteia și înaintea Ta, căci Numele Tău este în Casa aceasta; vom striga către Tine din mijlocul strâmtorării noastre, și Tu ne vei asculta și ne vei mântui!”", "Acum iată, fiii lui Amon și ai lui Moab și cei din muntele Seir, la care n-ai îngăduit lui Israel să intre când venea din țara Egiptului (căci s-a abătut de la ei și nu i-a nimicit),", "iată-i cum ne răsplătesc acum, venind să ne izgonească din moștenirea Ta, pe care ne-ai dat-o în stăpânire!", "„O, Dumnezeul nostru, nu-i vei judeca Tu pe ei? Căci noi suntem fără putere înaintea acestei mari mulțimi care înaintează împotriva noastră și nu știm ce să facem, dar ochii noștri sunt îndreptați spre Tine!”", "Tot Iuda stătea în picioare înaintea DOMNULUI, cu pruncii, nevestele și fiii lor.", "Atunci Duhul DOMNULUI a venit în mijlocul adunării peste Iahaziel, fiul lui Zaharia, fiul lui Benaia, fiul lui Ieiel, fiul lui Matania, levitul, dintre fiii lui Asaf.", "Și Iahaziel a zis: „Ascultați, tot Iuda și locuitorii din Ierusalim, și tu, împărate Iosafat! Așa vă vorbește DOMNUL: «Nu vă temeți și nu vă înspăimântați dinaintea acestei mari mulțimi, căci nu voi veți lupta, ci Dumnezeu.»”", "Mâine coborâți-vă împotriva lor. Ei se vor sui pe dealul Țiț, și-i veți găsi la capătul văii, în fața pustiului Ieruel.", "„Nu veți avea de luptat în lupta aceasta: așezați-vă, stați acolo și veți vedea izbăvirea pe care v-o va da DOMNUL. Iuda și Ierusalim, nu vă temeți și nu vă înspăimântați; mâine, ieșiți-le înainte, și DOMNUL va fi cu voi!”", "Iosafat s-a plecat cu fața la pământ, și tot Iuda și locuitorii Ierusalimului s-au aruncat înaintea DOMNULUI să se închine înaintea Lui.", "Leviții dintre fiii chehatiților și dintre fiii coreiților s-au sculat și au lăudat cu glas tare și puternic pe DOMNUL Dumnezeul lui Israel.", "A doua zi, au pornit dis-de-dimineață spre pustiul Tecoa. La plecarea lor, Iosafat a venit și a zis: „Ascultați-mă, Iuda și locuitorii Ierusalimului! Încredeți-vă în DOMNUL Dumnezeul vostru, și veți fi întăriți; încredeți-vă în prorocii Lui, și veți izbuti.”", "Apoi, în învoire cu poporul, a numit niște cântăreți care, îmbrăcați cu podoabe sfinte și mergând înaintea oștirii, lăudau pe DOMNUL și ziceau: „Lăudați pe DOMNUL, căci îndurarea Lui ține în veac!”", "În clipa când au început cântările și laudele, DOMNUL a pus o pândă împotriva fiilor lui Amon și ai lui Moab și împotriva celor din muntele Seir, care veniseră împotriva lui Iuda. Și au fost bătuți.", "Fiii lui Amon și ai lui Moab s-au aruncat asupra locuitorilor din muntele Seir ca să-i nimicească cu desăvârșire și să-i prăpădească. Și, după ce au isprăvit cu locuitorii din Seir, s-au ajutat unii pe alții să se nimicească.", "Când a ajuns Iuda pe înălțimea de unde se zărește pustiul, s-au uitat înspre mulțime, și iată că ei erau niște trupuri moarte întinse pe pământ, și nimeni nu scăpase.", "Iosafat și poporul său s-au dus să ia prăzile; au găsit printre trupuri multe bogății și lucruri scumpe și au luat atât de multe că n-au putut să le ducă pe toate. Trei zile au prădat, căci era multă pradă.", "A patra zi, s-au strâns în valea Beraca unde au binecuvântat pe DOMNUL; de aceea au numit locul acesta valea Beraca, nume care i-a rămas până în ziua de azi.", "Toți oamenii din Iuda și din Ierusalim, în frunte cu Iosafat, au plecat veseli și s-au întors la Ierusalim, căci DOMNUL îi umpluse de bucurie, izbăvindu-i de vrăjmașii lor.", "Au intrat în Ierusalim și în Casa DOMNULUI în sunete de lăute, de harpe și de trâmbițe.", "Groaza DOMNULUI a apucat toate împărățiile celorlalte țări, când au auzit că DOMNUL luptase împotriva vrăjmașilor lui Israel.", "Și împărăția lui Iosafat a fost liniștită, și Dumnezeul lui i-a dat pace de jur împrejur.", "Iosafat a domnit peste Iuda. Avea treizeci și cinci de ani când a ajuns împărat și a domnit douăzeci și cinci de ani la Ierusalim. Mama sa se chema Azuba, fata lui Șilhi.", "El a mers pe calea tatălui său, Asa, și nu s-a abătut deloc, făcând ce este bine înaintea DOMNULUI.", "Numai că înălțimile n-au fost îndepărtate, și poporul tot n-avea inima strâns lipită de Dumnezeul părinților săi.", "Celelalte fapte ale lui Iosafat, cele dintâi și cele de pe urmă, sunt scrise în istoria lui Iehu, fiul lui Hanani, care este cuprinsă în cartea împăraților lui Israel.", "După aceea, Iosafat, împăratul lui Iuda, s-a unit cu împăratul lui Israel, Ahazia, a cărui purtare era nelegiuită.", "S-a unit cu el ca să zidească niște corăbii, care să meargă la Tarsis, și au făcut corăbii la Ețion-Gheber.", "Atunci Eliezer, fiul lui Dodava din Mareșa, a prorocit împotriva lui Iosafat și a zis: „Pentru că te-ai unit cu Ahazia, DOMNUL ți-a nimicit lucrarea.” Corăbiile au fost sfărâmate și n-au putut să se ducă la Tarsis."],
    21: ["Iosafat a adormit cu părinții săi și a fost îngropat cu părinții săi în cetatea lui David. Și, în locul lui, a domnit fiul său Ioram.", "Ioram avea ca frați, fii ai lui Iosafat, pe Azaria, Iehiel, Zaharia, Azaria, Micael și Șefatia, toți fiii lui Iosafat, împăratul lui Israel.", "Tatăl lor le dăduse daruri însemnate în argint, în aur și în lucruri scumpe, împreună cu cetăți întărite în Iuda; dar împărăția a lăsat-o lui Ioram, pentru că el era întâiul născut.", "Când a luat Ioram în stăpânire împărăția tatălui său și când s-a întărit, a omorât cu sabia pe toți frații săi și pe vreo câțiva din capii lui Israel.", "Ioram avea treizeci și doi de ani când a ajuns împărat și a domnit opt ani la Ierusalim.", "El a umblat în calea împăraților lui Israel, cum făcuse casa lui Ahab, căci avea de nevastă pe o fată a lui Ahab, și a făcut ce este rău înaintea DOMNULUI.", "Dar DOMNUL n-a voit să piardă casa lui David, din pricina legământului pe care-l făcuse cu David și din pricina făgăduinței pe care o făcuse că îi va da întotdeauna o lumină, lui și fiilor lui.", "Pe vremea sa, Edom s-a răsculat împotriva stăpânirii lui Iuda și și-a pus un împărat.", "Ioram a pornit cu căpeteniile și cu toate carele sale. Sculându-se noaptea, a bătut pe edomiți, care-l înconjurau, și pe căpeteniile carelor lor.", "Răscoala lui Edom împotriva stăpânirii lui Iuda a ținut până în ziua de azi. În același timp s-a răsculat și Libna împotriva stăpânirii lui, pentru că părăsise pe DOMNUL Dumnezeul părinților săi.", "Ioram a făcut chiar înălțimi în munții lui Iuda. A târât pe locuitorii Ierusalimului la curvie și a amăgit pe Iuda.", "I-a venit o scrisoare de la prorocul Ilie, care zicea: „Așa vorbește DOMNUL Dumnezeul tatălui tău David: «Pentru că n-ai umblat în căile tatălui tău Iosafat și în căile lui Asa, împăratul lui Iuda,", "ci ai umblat în calea împăraților lui Israel; pentru că ai târât la curvie pe Iuda și locuitorii Ierusalimului, cum a făcut casa lui Ahab față de Israel; și pentru că ai omorât pe frații tăi, care erau mai buni decât tine și care făceau parte din însăși casa tatălui tău,", "iată, DOMNUL va lovi cu o mare urgie pe poporul tău, pe fiii tăi, pe nevestele tale și tot ce este al tău,", "iar pe tine te va lovi cu o boală grea, cu o boală de măruntaie care se va îngreuia din zi în zi până când îți vor ieși măruntaiele din pricina tăriei bolii.»”", "Și DOMNUL a ațâțat împotriva lui Ioram duhul filistenilor și al arabilor, care sunt în vecinătatea etiopienilor.", "S-au suit împotriva lui Iuda, au năvălit în el, au jefuit toate bogățiile care se aflau în casa împăratului și i-au luat fiii și nevestele, așa încât nu i-a mai rămas alt fiu decât Ioahaz, cel mai tânăr dintre fiii săi.", "După toate acestea, DOMNUL l-a lovit cu o boală de măruntaie, care era fără leac.", "Ea s-a îngreuiat din zi în zi, și pe la sfârșitul anului al doilea i-au ieșit lui Ioram măruntaiele din pricina tăriei bolii. A murit în dureri grele. Și poporul lui n-a ars tămâie în cinstea lui, cum făcuse pentru părinții lui.", "„Avea treizeci și doi de ani când a ajuns împărat și a domnit opt ani la Ierusalim. A murit fără să lase părere de rău în urmă, și l-au îngropat în cetatea lui David, dar nu în mormintele împăraților.”"],
    22: ["Locuitorii Ierusalimului au pus împărat în locul lui pe Ahazia, fiul lui cel mai tânăr; căci oastea venită în tabără cu arabii omorâse pe toți cei mai mari în vârstă. Astfel a început să domnească Ahazia, fiul lui Ioram, împăratul lui Iuda.", "Ahazia avea patruzeci și doi de ani, când a ajuns împărat, și a domnit un an la Ierusalim. Mama sa se chema Atalia, fata lui Omri.", "El a umblat în căile casei lui Ahab, căci mama sa îi dădea sfaturi nelegiuite.", "A făcut ce este rău înaintea DOMNULUI, ca și casa lui Ahab, căci după moartea tatălui său, ei îi erau sfetnici, spre pierzarea lui.", "Târât de sfatul lor, s-a dus cu Ioram, fiul lui Ahab, împăratul lui Israel, la război împotriva lui Hazael, împăratul Siriei, la Ramot în Galaad. Sirienii au rănit pe Ioram.", "Ioram s-a întors să se vindece la Izreel de rănile pe care i le făcuseră sirienii la Rama, când se bătea împotriva lui Hazael, împăratul Siriei. Azaria, fiul lui Ioram, împăratul lui Iuda, s-a coborât să vadă pe Ioram, fiul lui Ahab, la Izreel, pentru că era bolnav.", "Prin voia lui Dumnezeu și spre pierzarea lui a venit Ahazia la Ioram. Când a ajuns, a ieșit cu Ioram să se ducă înaintea lui Iehu, fiul lui Nimși, pe care-l unsese DOMNUL ca să piardă casa lui Ahab.", "Și, pe când făcea Iehu judecată împotriva casei lui Ahab, a dat peste capii lui Iuda și peste fiii fraților lui Ahazia, care erau în slujba lui Ahazia, și i-a omorât.", "Au căutat pe Ahazia și l-au prins în Samaria, unde se ascunsese. L-au adus la Iehu și l-au omorât. Apoi l-au îngropat, căci ziceau: „Este fiul lui Iosafat, care căuta pe DOMNUL din toată inima lui.” Casa lui Ahazia nu mai avea putere să păstreze domnia.", "Atalia, mama lui Ahazia, văzând că fiul ei a murit, s-a sculat și a omorât tot neamul împărătesc al casei lui Iuda.", "Dar Ioșabeat, fata împăratului, a luat pe Ioas, fiul lui Ahazia, l-a ridicat din mijlocul fiilor împăratului, când au fost omorâți, și l-a pus cu doica lui în odaia paturilor. Astfel l-a ascuns Ioșabeat, fata împăratului Ioram, nevasta preotului Iehoiada și sora lui Ahazia, de privirile Ataliei, care nu l-a omorât.", "A stat șase ani ascuns cu ei în Casa lui Dumnezeu. Și în țară domnea Atalia."],
    23: ["În al șaptelea an, Iehoiada s-a îmbărbătat și a făcut legământ cu căpeteniile peste sute. Aceștia erau: Azaria, fiul lui Ieroham, Ismael, fiul lui Iohanan, Azaria, fiul lui Obed, Maaseia, fiul lui Adaia, și Elișafat, fiul lui Zicri.", "Au străbătut toată țara lui Iuda și au strâns pe leviții din toate cetățile lui Iuda și pe capii de familii din Israel; și au venit la Ierusalim.", "Toată adunarea a făcut legământ cu împăratul în Casa lui Dumnezeu. Și Iehoiada le-a zis: „Iată că fiul împăratului va domni, cum a spus DOMNUL cu privire la fiii lui David.”", "Iată ce veți face. A treia parte din voi, care intră de slujbă în ziua Sabatului, preoți și leviți, să facă paza pragurilor;", "altă treime să stea în casa împăratului, și o treime la poarta Iesod. Tot poporul să fie în curțile Casei DOMNULUI.", "Nimeni să nu intre în Casa DOMNULUI, afară de preoții și leviții de slujbă: ei să intre, căci sunt sfinți. Și tot poporul să facă de strajă cu privire la porunca DOMNULUI.", "„Leviții să înconjoare pe împărat din toate părțile, fiecare cu armele în mână, și oricine va intra în Casă să fie omorât. Voi să fiți pe lângă împărat, când va intra și când va ieși.”", "Leviții și tot Iuda au împlinit toate poruncile pe care le dăduse preotul Iehoiada. Și-au luat fiecare oamenii lui, pe cei ce intrau în slujbă și pe cei ce ieșeau din slujbă în ziua Sabatului; căci preotul Iehoiada nu scutise pe niciuna din cete.", "Preotul Iehoiada a dat sutașilor sulițele și scuturile, mari și mici, care veneau de la împăratul David și care se aflau în Casa lui Dumnezeu.", "A așezat tot poporul, fiecare cu arma în mână, de la partea dreaptă până la partea stângă a Casei, lângă altar și lângă Casă, de jur împrejurul împăratului.", "Au adus înainte pe fiul împăratului, i-au pus cununa împărătească și mărturia și l-au făcut împărat. Și Iehoiada și fiii săi l-au uns și au zis: „Trăiască împăratul!”", "Atalia a auzit zarva poporului, care alerga și mărea pe împărat, și a venit la popor în Casa DOMNULUI.", "S-a uitat. Și iată că împăratul stătea pe scaunul său împărătesc la intrare. Căpeteniile și trâmbițele erau lângă împărat; tot poporul țării se bucura și sunau din trâmbițe, iar cântăreții cu instrumentele de muzică ziceau cântările de laudă. Atalia și-a sfâșiat hainele și a zis: „Trădare! Trădare!”", "Atunci preotul Iehoiada, scoțând pe sutași, care erau în fruntea oștirii, le-a zis: „Scoateți-o afară din șiruri, și oricine o va urma să fie ucis.” Căci preotul zisese: „N-o omorâți în Casa DOMNULUI.”", "I-au făcut loc și s-a dus la casa împăratului pe intrarea porții cailor; și au omorât-o acolo.", "Iehoiada a făcut între el, tot poporul și împărat, un legământ prin care aveau să fie poporul DOMNULUI.", "Tot poporul a intrat în casa lui Baal și au dărâmat-o; i-au sfărâmat altarele și chipurile și au ucis înaintea altarelor pe Matan, preotul lui Baal.", "Iehoiada a încredințat slujbele Casei DOMNULUI în mâinile preoților, leviților, pe care-i împărțise David în Casa DOMNULUI ca să aducă arderi de tot DOMNULUI, cum este scris în Legea lui Moise, în mijlocul bucuriilor și cântărilor, după rânduiala lui David.", "A pus ușieri la porțile Casei DOMNULUI, ca să nu intre nimeni spurcat prin ceva.", "A luat pe sutași, pe oamenii cu vază, pe cei ce aveau putere peste popor și pe tot poporul țării, și a coborât pe împărat din Casa DOMNULUI. Au intrat în casa împăratului pe poarta de sus și au pus pe împărat pe scaunul de domnie al împărăției.", "Tot poporul țării se bucura, și cetatea era liniștită. Pe Atalia o omorâseră cu sabia."],
    24: ["Ioas avea șapte ani când a ajuns împărat și a domnit patruzeci de ani la Ierusalim. Mama sa se chema Țibia din Beer-Șeba.", "Ioas a făcut ce este bine înaintea DOMNULUI în tot timpul vieții preotului Iehoiada.", "Iehoiada a luat pentru Ioas două neveste, și Ioas a născut fii și fiice.", "După aceea, Ioas și-a pus de gând să dreagă Casa DOMNULUI.", "A strâns pe preoți și pe leviți și le-a zis: „Duceți-vă prin cetățile lui Iuda și strângeți bani din tot Israelul, pe fiecare an, pentru dregerea Casei Dumnezeului vostru. Și grăbiți-vă cu lucrul acesta.” Dar leviții nu s-au grăbit.", "Împăratul a chemat pe marele preot Iehoiada și i-a zis: „Pentru ce n-ai vegheat ca leviții să strângă din Iuda și din Ierusalim darea poruncită de Moise, robul DOMNULUI, și pusă pe adunarea lui Israel pentru Cortul mărturiei?”", "„Căci nelegiuita aceea de Atalia și fiii ei au pustiit Casa lui Dumnezeu și au întrebuințat în slujba Baalilor toate lucrurile închinate Casei DOMNULUI.”", "Atunci împăratul a poruncit să se facă o ladă și să se pună afară la poarta Casei DOMNULUI.", "Și s-a dat de veste în Iuda și în Ierusalim ca să se aducă DOMNULUI darea pusă de Moise, robul DOMNULUI, pe Israel în pustiu.", "Toate căpeteniile și tot poporul s-au bucurat de lucrul acesta și au adus și au aruncat în ladă tot ce aveau de plătit.", "Când vedeau leviții că e mult argint în ladă și că era vremea ca s-o dea în mâinile dregătorilor împăratului, venea logofătul împăratului și slujbașul marelui preot și goleau lada. Apoi o luau și o puneau iarăși la loc. Așa făceau în fiecare zi, și au strâns mult argint.", "Împăratul și Iehoiada îl dădeau meșterilor însărcinați cu facerea lucrării în Casa DOMNULUI, care tocmeau cioplitori de piatră și tâmplari, ca să dreagă Casa DOMNULUI, precum și lucrători în fier și aramă, ca să dreagă Casa DOMNULUI.", "Lucrătorii s-au apucat de lucru și au isprăvit ce era de dres; au pus Casa lui Dumnezeu iarăși în stare bună și au întărit-o.", "Când au isprăvit, au adus înaintea împăratului și înaintea lui Iehoiada argintul care mai rămăsese. Și cu el au făcut unelte pentru Casa DOMNULUI, unelte pentru slujbă și pentru arderile de tot, pahare și alte scule de aur și de argint. Și, în tot timpul vieții lui Iehoiada, au adus necurmat arderi de tot în Casa DOMNULUI.", "Iehoiada a murit bătrân și sătul de zile. La moarte, avea o sută treizeci de ani.", "L-au îngropat în cetatea lui David la un loc cu împărații, pentru că făcuse bine în Israel și față de Dumnezeu, și față de Casa Lui.", "După moartea lui Iehoiada, căpeteniile lui Iuda au venit și s-au închinat înaintea împăratului. Atunci împăratul i-a ascultat.", "Și au părăsit Casa DOMNULUI Dumnezeului părinților lor și au slujit Așerelor și idolilor. Mânia DOMNULUI a venit asupra lui Iuda și asupra Ierusalimului, pentru că se făcuseră vinovați în felul acesta.", "DOMNUL a trimis la ei proroci să-i întoarcă înapoi la El, dar n-au ascultat de înștiințările pe care le-au primit.", "Zaharia, fiul preotului Iehoiada, a fost îmbrăcat cu Duhul lui Dumnezeu. El s-a înfățișat înaintea poporului și i-a zis: „Așa vorbește Dumnezeu: «Pentru ce călcați poruncile DOMNULUI? Nu veți propăși. Pentru că ați părăsit pe DOMNUL, și El vă va părăsi.»”", "Și au uneltit împotriva lui și l-au ucis cu pietre, din porunca împăratului, în curtea Casei DOMNULUI.", "Împăratul Ioas nu și-a adus aminte de bunăvoința pe care o avusese față de el Iehoiada, tatăl lui Zaharia, și a omorât pe fiul lui. Zaharia a zis când a murit: „DOMNUL să vadă și să judece!”", "După trecerea anului, oastea sirienilor s-a suit împotriva lui Ioas și a venit în Iuda și la Ierusalim. Au omorât din popor pe toate căpeteniile poporului și au trimis împăratului toată prada la Damasc.", "Oastea sirienilor a venit cu un mic număr de oameni. Totuși DOMNUL a dat în mâinile lor o oaste foarte însemnată, pentru că părăsiseră pe DOMNUL Dumnezeul părinților lor. Astfel au pedepsit sirienii pe Ioas.", "Când au plecat de la el, după ce-l lăsaseră în mari suferințe, slujitorii lui au uneltit împotriva lui din pricina sângelui fiilor preotului Iehoiada. L-au omorât în patul lui, și a murit. L-au îngropat în cetatea lui David, dar nu l-au îngropat în mormintele împăraților.", "Iată pe cei ce au uneltit împotriva lui: Zabad, fiul Șimeatei, o femeie amonită, și Iozabad, fiul Șimritei, o femeie moabită.", "„Cât despre fiii lui, despre mărimea poverilor puse asupra lui și despre dregerea Casei lui Dumnezeu, toate acestea sunt scrise în istoria din cartea împăraților. În locul lui a domnit fiul său Amația.”"],
    25: ["Amația a ajuns împărat la vârsta de douăzeci și cinci de ani și a domnit douăzeci și nouă de ani la Ierusalim. Mama sa se chema Ioadan din Ierusalim.", "El a făcut ce este bine înaintea DOMNULUI, dar cu o inimă care nu era în totul dată Lui.", "Când s-a întărit domnia în mâinile lui, a omorât pe slujitorii care uciseseră pe împăratul, tatăl său.", "Dar n-a omorât pe fiii lor, căci a lucrat potrivit cu ceea ce este scris în Lege, în cartea lui Moise, unde DOMNUL dă porunca aceasta: „Să nu se omoare părinții pentru copii, și să nu se omoare copiii pentru părinți; ci fiecare să fie omorât pentru păcatul lui.”", "Amația a strâns pe oamenii din Iuda și i-a pus după casele părintești, căpetenii peste mii și căpetenii peste sute, pentru tot Iuda și Beniamin. Le-a făcut numărătoarea de la vârsta de douăzeci de ani în sus și a găsit trei sute de mii de oameni aleși, în stare să poarte armele, mânuind sulița și scutul.", "A mai tocmit cu plată din Israel o sută de mii de viteji, cu o sută de talanți de argint.", "Un om al lui Dumnezeu a venit la el și a zis: „Împărate, să nu meargă cu tine oastea lui Israel, căci DOMNUL nu este cu Israel, nu este cu toți acești fii ai lui Efraim.”", "„Dacă mergi cu ei, chiar dacă ai face la luptă fapte de vitejie, să știi că Dumnezeu te va face să cazi înaintea vrăjmașului. Căci Dumnezeu are putere să te ajute și să te facă să cazi.”", "Amația a zis omului lui Dumnezeu: „Dar ce să fac cu cei o sută de talanți pe care i-am dat oștii lui Israel?” Omul lui Dumnezeu a răspuns: „DOMNUL poate să-ți dea mult mai mult decât atât.”", "Atunci Amația a despărțit ceata care-i venise din Efraim și a poruncit ca oamenii aceștia să se întoarcă acasă. Dar ei s-au mâniat foarte tare pe Iuda și au plecat acasă cu mare furie.", "Amația s-a îmbărbătat și și-a dus poporul în Valea Sării, unde a bătut zece mii de oameni din fiii lui Seir.", "Și fiii lui Iuda au prins din ei zece mii de inși vii, pe care i-au dus pe vârful unei stânci, de unde i-au prăvălit în vale, așa încât toți au fost zdrobiți.", "Însă oamenii din ceata căreia îi dăduse drumul ca să nu meargă la război cu el au năvălit în cetățile lui Iuda, de la Samaria până la Bet-Horon, au ucis acolo trei mii de inși și au luat multe prăzi.", "Când s-a întors Amația de la înfrângerea edomiților, a adus pe dumnezeii fiilor lui Seir și i-a pus dumnezei pentru el; s-a închinat înaintea lor și le-a adus tămâie.", "Atunci DOMNUL S-a aprins de mânie împotriva lui Amația și a trimis la el pe un proroc, care i-a zis: „Pentru ce ai căutat pe dumnezeii poporului acestuia, când ei n-au putut să-și izbăvească poporul din mâna ta?”", "Pe când vorbea el, Amația i-a zis: „Oare te-am făcut sfetnic al împăratului? Pleacă! Pentru ce vrei să fii lovit?” Prorocul a plecat, zicând: „Știu acum că Dumnezeu a hotărât să te nimicească, pentru că ai făcut lucrul acesta și n-ai ascultat sfatul meu.”", "După ce s-a sfătuit, Amația, împăratul lui Iuda, a trimis să spună lui Ioas, fiul lui Ioahaz, fiul lui Iehu, împăratul lui Israel: „Vino, să ne vedem față în față!”", "Ioas, împăratul lui Israel, a trimis să-i spună lui Amația, împăratul lui Iuda: „Spinul din Liban a trimis să-i spună cedrului din Liban: «Dă-o pe fiica ta de soție fiului meu!» Dar o fiară sălbatică din Liban a trecut și a călcat spinul în picioare.”", "„Tu te gândești că ai bătut pe edomiți, și de aceea ți se înalță inima ca să te mândrești. Acum stai mai bine acasă. Pentru ce să stârnești un rău care ți-ar aduce pieirea ta și a lui Iuda?”", "Dar Amația nu l-a ascultat, fiindcă Dumnezeu hotărâse să-i dea în mâinile vrăjmașului, căci căutaseră pe dumnezeii Edomului.", "Și Ioas, împăratul lui Israel, s-a suit; și s-au văzut în față, el și Amația, împăratul lui Iuda, la Bet-Șemeșul lui Iuda.", "Iuda a fost bătut de Israel, și fiecare a fugit în cortul lui.", "Ioas, împăratul lui Israel, a luat la Bet-Șemeș pe Amația, împăratul lui Iuda, fiul lui Ioas, fiul lui Ioahaz. L-a adus la Ierusalim și a făcut o spărtură de patru sute de coți în zidul Ierusalimului, de la poarta lui Efraim până la poarta unghiului.", "A luat tot aurul și argintul, și toate vasele care se aflau în Casa lui Dumnezeu, la Obed-Edom, și vistieriile casei împăratului. A luat și ostatici și s-a întors la Samaria.", "Amația, fiul lui Ioas, împăratul lui Iuda, a trăit cincisprezece ani după moartea lui Ioas, fiul lui Ioahaz, împăratul lui Israel.", "Celelalte fapte ale lui Amația, cele dintâi și cele de pe urmă, nu sunt scrise oare în cartea împăraților lui Iuda și Israel?", "De când s-a abătut Amația de la DOMNUL, s-a făcut împotriva lui o uneltire la Ierusalim, și el a fugit la Lachis. Dar l-au urmărit la Lachis și l-au omorât.", "L-au adus pe cai și l-au îngropat cu părinții săi în cetatea lui Iuda."],
    26: ["Tot poporul din Iuda a luat pe Ozia, care era în vârstă de șaisprezece ani, și l-a pus împărat în locul tatălui său, Amația.", "Ozia a întărit Elotul și l-a adus iarăși sub stăpânirea lui Iuda, după ce a adormit împăratul cu părinții săi.", "Ozia avea șaisprezece ani când a ajuns împărat și a domnit cincizeci și doi de ani la Ierusalim. Mama sa se chema Iecolia din Ierusalim.", "El a făcut ce este bine înaintea DOMNULUI, întocmai cum făcuse tatăl său Amația.", "A căutat pe Dumnezeu în timpul vieții lui Zaharia, care pricepea vedeniile lui Dumnezeu. Și în timpul când a căutat pe DOMNUL, Dumnezeu l-a făcut să propășească.", "A pornit cu război împotriva filistenilor. A dărâmat zidurile Gatului, zidurile Iabnei și zidurile Asdodului și a zidit cetăți în ținutul Asdodului și între filisteni.", "Dumnezeu l-a ajutat împotriva filistenilor, împotriva arabilor care locuiau la Gur-Baal și împotriva maoniților.", "Amoniții aduceau daruri lui Ozia, și faima lui s-a întins până la hotarele Egiptului, căci a ajuns foarte puternic.", "Ozia a zidit turnuri la Ierusalim, pe poarta unghiului, pe poarta văii și pe unghi, și le-a întărit.", "A zidit turnuri în pustiu și a săpat multe fântâni, pentru că avea multe turme în văi și în câmpie, și plugari și vieri în munți și la Carmel, căci îi plăcea lucrarea pământului.", "Ozia avea o oaste de ostași care mergeau la război în cete, socotite după numărătoarea făcută de logofătul Ieiel și dregătorul Maaseia și puse sub poruncile lui Hanania, una din căpeteniile împăratului.", "Tot numărul capilor caselor părintești, al vitejilor, era de două mii șase sute.", "Ei porunceau peste o oaste de trei sute șapte mii cinci sute de ostași în stare să ajute pe împărat împotriva vrăjmașului.", "Ozia le-a dat pentru toată oștirea scuturi, sulițe, coifuri, platoșe, arcuri și praștii.", "A făcut la Ierusalim mașini iscodite de un meșter, care aveau să fie așezate pe turnuri și pe unghiuri ca să arunce săgeți și pietre mari. Faima lui s-a întins până departe, căci a fost ajutat în chip minunat până ce a ajuns foarte puternic.", "Dar când a ajuns puternic, inima i s-a înălțat și l-a dus la pieire. A păcătuit împotriva DOMNULUI Dumnezeului său, intrând în Templul DOMNULUI ca să ardă tămâie pe altarul tămâierii.", "Preotul Azaria a intrat după el cu optzeci de preoți ai DOMNULUI, oameni de inimă.", "care s-au împotrivit împăratului Ozia și i-au zis: „N-ai drept, Ozia, să aduci tămâie DOMNULUI! Dreptul acesta îl au preoții, fiii lui Aaron, care au fost sfințiți ca s-o aducă. Ieși din Sfântul Locaș, căci faci un păcat! Și lucrul acesta nu-ți va face cinste înaintea DOMNULUI Dumnezeu.”", "Ozia s-a mâniat. În mână avea o cădelniță. Și, cum s-a mâniat pe preoți, i-a izbucnit lepra pe frunte, în fața preoților, în Casa DOMNULUI, lângă altarul tămâierii.", "Marele preot Azaria și toți preoții și-au îndreptat privirile spre el, și iată că era plin de lepră pe frunte. L-au scos repede afară, și el însuși s-a grăbit să iasă, pentru că DOMNUL îl lovise.", "Împăratul Ozia a fost lepros până în ziua morții și a locuit într-o casă deosebită ca lepros, căci a fost izgonit din Casa DOMNULUI. Și fiul său Iotam era în fruntea casei împăratului și judeca poporul țării.", "Celelalte fapte ale lui Ozia, cele dintâi și cele de pe urmă, au fost scrise de Isaia, fiul lui Amoț, prorocul.", "Ozia a adormit cu părinții săi. Și l-au îngropat cu părinții săi în ogorul de înmormântare al împăraților, căci ziceau: „Este lepros.” Fiul său Iotam a domnit în locul lui."],
    27: ["Iotam avea douăzeci și cinci de ani când a ajuns împărat și a domnit șaisprezece ani la Ierusalim. Mama sa se chema Ierușa, fata lui Țadoc.", "El a făcut ce este bine înaintea DOMNULUI, întocmai cum făcuse tatăl său, Ozia. Numai că n-a intrat în Templul DOMNULUI. Totuși poporul se strica mereu.", "Iotam a zidit poarta de sus a Casei DOMNULUI și a zidit mult pe zidul Ofelului.", "A zidit cetăți pe muntele lui Iuda și cetățui și turnuri în dumbrăvi.", "A fost în război cu împăratul fiilor lui Amon și i-a biruit. Fiii lui Amon i-au dat în anul acela o sută de talanți de argint, zece mii de cori de grâu și zece mii de orz; și i-au plătit tot atât pe anul al doilea și al treilea.", "Iotam a ajuns puternic, pentru că și-a urmat necurmat căile înaintea DOMNULUI Dumnezeului său.", "Celelalte fapte ale lui Iotam, toate războaiele lui și tot ce a făcut el, sunt scrise în cartea împăraților lui Israel și Iuda.", "El avea douăzeci și cinci de ani când a ajuns împărat și a domnit șaisprezece ani la Ierusalim.", "Iotam a adormit cu părinții săi, și l-au îngropat în cetatea lui David. Și, în locul lui, a domnit fiul său Ahaz."],
    28: ["Ahaz avea douăzeci de ani când a ajuns împărat și a domnit șaisprezece ani la Ierusalim. El n-a făcut ce este bine înaintea DOMNULUI, cum făcuse tatăl său David.", "A umblat în căile împăraților lui Israel; și a făcut chiar chipuri turnate pentru Baali,", "a ars tămâie în valea fiilor lui Hinom și a trecut pe fiii săi prin foc, după urâciunile neamurilor pe care le izgonise DOMNUL dinaintea copiilor lui Israel.", "Aducea jertfe și tămâie pe înălțimi, pe dealuri și sub orice copac verde.", "DOMNUL Dumnezeul său l-a dat în mâinile împăratului Siriei. Sirienii l-au bătut și i-au luat un mare număr de prinși de război, pe care i-au dus la Damasc. A fost dat și în mâinile împăratului lui Israel, care i-a pricinuit o mare înfrângere.", "Pecah, fiul lui Remalia, a ucis într-o singură zi în Iuda o sută douăzeci de mii de oameni, toți vitejii, pentru că părăsiseră pe DOMNUL Dumnezeul părinților lor.", "Zicri, un războinic din Efraim, a ucis pe Maaseia, fiul împăratului, pe Azricam, căpetenia casei împărătești, și pe Elcana, care era al doilea după împărat.", "Copiii lui Israel au luat dintre frații lor două sute de mii de prinși de război, femei, fiii și fiice, și le-au luat multă pradă, pe care au adus-o la Samaria.", "Acolo era un proroc al DOMNULUI, numit Oded. El a ieșit înaintea oștirii care se întorcea la Samaria și le-a zis: „În mânia Sa împotriva lui Iuda i-a dat DOMNUL Dumnezeul părinților voștri în mâinile voastre, și voi i-ați ucis cu o furie care s-a ridicat până la ceruri.”", "Și credeți acum că veți face din copiii lui Iuda și din Ierusalim robii și roabele voastre? Dar voi nu sunteți vinovați înaintea DOMNULUI Dumnezeului vostru?", "„Ascultați-mă, dar, și dați drumul acestor prinși pe care i-ați luat dintre frații voștri; căci mânia aprinsă a DOMNULUI este peste voi!”", "Unii dintre capii fiilor lui Efraim: Azaria, fiul lui Iohanan, Berechia, fiul lui Meșilemot, Ezechia, fiul lui Șalum, și Amasa, fiul lui Hadlai, s-au ridicat împotriva celor ce se întorceau de la oștire.", "și le-au zis: „Să nu aduceți aici pe acești prinși de război. Căci, după ce că suntem vinovați înaintea DOMNULUI, voi vreți să mai și adăugați la păcatele și la greșelile noastre. Suntem foarte vinovați, și mânia aprinsă a DOMNULUI este peste Israel.”", "Ostașii au lăsat pe prinșii de război și prada înaintea căpeteniilor și înaintea întregii adunări.", "Și oamenii numiți pe nume pentru aceasta s-au sculat și au luat pe prinșii de război, au îmbrăcat cu prada pe toți cei ce erau goi, le-au dat haine și încălțăminte, le-au dat să mănânce și să bea, i-au uns, au încălecat pe măgari pe toți cei osteniți și i-au adus la Ierihon, cetatea finicilor, la frații lor. Apoi s-au întors la Samaria.", "Pe vremea aceea, împăratul Ahaz a trimis să ceară ajutor de la împărații Asiriei.", "Edomiții au venit iarăși, au bătut pe Iuda și le-au luat prinși de război.", "Filistenii au năvălit în cetățile din câmpie și din partea de miazăzi a lui Iuda; au luat Bet-Șemeșul, Aialonul, Ghederotul, Soco și satele lui, Timna și satele ei, Ghimzo și satele lui, și s-au așezat acolo.", "Căci DOMNUL a smerit pe Iuda, din pricina lui Ahaz, împăratul lui Israel, care avusese o purtare fără frâu în Iuda și păcătuise împotriva DOMNULUI.", "Tilgat-Pilneser, împăratul Asiriei, a venit împotriva lui, s-a purtat cu el cum s-ar purta cu un vrăjmaș și nu l-a ajutat.", "Căci Ahaz a prădat Casa DOMNULUI, casa împăratului și a mai marilor, ca să facă daruri împăratului Asiriei; dar nu i-a ajutat la nimic.", "Pe vremea aceea, chiar când era la strâmtorare, a păcătuit și mai mult împotriva DOMNULUI, el, împăratul Ahaz.", "A adus jertfă dumnezeilor Damascului, care-l bătuseră, și a zis: „Fiindcă dumnezeii împăraților Siriei le vin în ajutor, le voi aduce și eu jertfe, ca să-mi ajute.” Dar tocmai ei au dus la căderea lui și a întregului Israel.", "Ahaz a strâns uneltele din Casa lui Dumnezeu și a făcut bucăți uneltele din Casa lui Dumnezeu. A închis ușile Casei DOMNULUI, și-a făcut altare în toate colțurile Ierusalimului.", "Și a ridicat înălțimi în fiecare cetate a lui Iuda, ca să aducă tămâie altor dumnezei. Și a mâniat astfel pe DOMNUL Dumnezeul părinților săi.", "Celelalte fapte ale lui și toate căile lui, cele dintâi și cele de pe urmă, sunt scrise în cartea împăraților lui Iuda și Israel.", "Ahaz a adormit cu părinții săi și a fost îngropat în cetatea Ierusalimului, căci nu l-au pus în mormintele împăraților lui Israel. Și, în locul lui, a domnit fiul său Ezechia."],
    29: ["Ezechia a ajuns împărat la vârsta de douăzeci și cinci de ani și a domnit douăzeci și nouă de ani la Ierusalim. Mama sa se chema Abia, fata lui Zaharia.", "El a făcut ce este bine înaintea DOMNULUI, întocmai cum făcuse tatăl său David.", "În anul întâi al domniei lui, în luna întâi, a deschis ușile Casei DOMNULUI și le-a dres.", "A adus pe preoți și pe leviți, pe care i-a strâns în locul deschis dinspre răsărit,", "și le-a zis: „Ascultați-mă, leviților! Acum sfințiți-vă, sfințiți Casa DOMNULUI Dumnezeului părinților voștri și scoateți afară din Sfântul Locaș ce este necurat.”", "Căci părinții noștri au păcătuit, au făcut ce este rău înaintea DOMNULUI Dumnezeului nostru. L-au părăsit, și-au abătut privirile de la Cortul DOMNULUI și i-au întors spatele.", "Au închis chiar ușile pridvorului și au stins candelele, și n-au adus Dumnezeului lui Israel nici tămâie, nici arderi de tot în Sfântul Locaș.", "De aceea mânia DOMNULUI a fost peste Iuda și peste Ierusalim și i-a făcut de groază, de spaimă și de bătaie de joc, cum vedeți cu ochii voștri.", "Și din pricina aceasta au căzut părinții noștri uciși de sabie, și fiii noștri, fiicele noastre și nevestele noastre sunt în robie.", "Am de gând, dar, să fac legământ cu DOMNUL Dumnezeul lui Israel, pentru ca mânia Lui aprinsă să se abată de la noi.", "„Acum, fiilor, nu mai stați nepăsători; căci voi ați fost aleși de DOMNUL ca să stați în slujbă înaintea Lui, să fiți slujitorii Lui și să-I aduceți tămâie.”", "Și leviții s-au sculat: Mahat, fiul lui Amasai, Ioel, fiul lui Azaria, din fiii chehatiților; și din fiii merariților: Chis, fiul lui Abdi, Azaria, fiul lui Iehaleleel; și din gherșoniți: Ioah, fiul lui Zima, Eden, fiul lui Ioah;", "și din fiii lui Elițafan: Șimri și Ieiel; și din fiii lui Asaf: Zaharia și Matania;", "și din fiii lui Heman: Iehiel și Șimei; și din fiii lui Iedutun: Șemaia și Uziel.", "Au adunat pe frații lor și, după ce s-au sfințit, au venit să curețe și Casa DOMNULUI, după porunca împăratului și după cuvintele DOMNULUI.", "Preoții au intrat înăuntrul Casei DOMNULUI ca s-o curețe; au scos toate necurățiile pe care le-au găsit în Templul DOMNULUI și le-au pus în curtea Casei DOMNULUI, unde le-au adunat leviții ca să le ducă afară în pârâul Chedron.", "Au început aceste curățări în ziua întâi a lunii întâi; în a opta zi a lunii au intrat în pridvorul DOMNULUI, și opt zile au curățat Casa DOMNULUI; în a șaisprezecea zi a lunii întâi isprăviseră.", "S-au dus apoi la împăratul Ezechia și au zis: „Am curățat toată Casa DOMNULUI, altarul arderilor de tot cu toate uneltele lui și masa pâinilor pentru punerea înainte cu toate uneltele ei.”", "„Am adus iarăși în stare bună și am curățat toate uneltele pe care le pângărise împăratul Ahaz în timpul domniei lui, când cu fărădelegile lui: sunt înaintea altarului DOMNULUI.”", "Împăratul Ezechia s-a sculat dis-de-dimineață, a strâns pe mai marii cetății și s-a suit la Casa DOMNULUI.", "Au adus șapte viței, șapte berbeci, șapte miei și șapte țapi, ca jertfă de ispășire pentru împărăție, pentru Sfântul Locaș și pentru Iuda. Împăratul a poruncit preoților, fiii lui Aaron, să le aducă pe altarul DOMNULUI.", "Preoții au înjunghiat boii și au strâns sângele, pe care l-au stropit pe altar; au înjunghiat berbecii și au stropit sângele pe altar; au înjunghiat mieii și au stropit sângele pe altar.", "Au adus apoi țapii ispășitori înaintea împăratului și înaintea adunării, care și-au pus mâinile peste ei.", "Preoții i-au înjunghiat și au făcut cu sângele lor o jertfă pentru păcat pe altar, ca ispășire pentru păcatele întregului Israel; căci pentru tot Israelul poruncise împăratul să se aducă arderea de tot și jertfa de ispășire.", "A pus pe leviți în Casa DOMNULUI cu chimvale, lăute și harpe, după rânduiala lui David, lui Gad, văzătorul împăratului, și prorocului Natan; căci astfel era porunca DOMNULUI dată prin prorocii Săi.", "Leviții au luat loc cu instrumentele lui David, și preoții, cu trâmbițele.", "Ezechia a poruncit să aducă arderea de tot pe altar; și, în clipa când a început arderea de tot, a început și cântarea DOMNULUI, în sunetul trâmbițelor și instrumentelor lui David, împăratul lui Israel.", "Toată adunarea s-a închinat, au cântat cântarea și au sunat din trâmbițe, până s-a isprăvit arderea de tot.", "Și când au isprăvit de adus arderea de tot, împăratul și toți cei ce erau cu el au îngenuncheat și s-au închinat.", "Apoi împăratul Ezechia și căpeteniile au zis leviților să laude pe DOMNUL cu cuvintele lui David și ale prorocului Asaf. L-au lăudat cu bucurie și s-au plecat, și s-au închinat.", "Ezechia a luat atunci cuvântul și a zis: „Acum, după ce v-ați sfințit în slujba DOMNULUI, apropiați-vă, aduceți dobitoacele pentru jertfă și aduceți jertfe de mulțumire la Casa DOMNULUI.” Adunarea a adus jertfe și daruri de mulțumire, iar toți cei cu inimă binevoitoare au adus arderi de tot.", "Numărul arderilor de tot aduse de adunare a fost de șaptezeci de boi, o sută de berbeci și două sute de miei; toate aceste vite au fost jertfite ca ardere de tot DOMNULUI.", "Și au mai închinat DOMNULUI șase sute de boi și trei mii de oi.", "Dar preoții erau în număr mic și n-au putut să despoaie toate arderile de tot; i-au ajutat frații lor, leviții, până s-a isprăvit lucrarea și până s-au sfințit și ceilalți preoți; căci leviții s-au sfințit mai degrabă decât preoții.", "De altfel erau foarte multe arderi de tot, cu grăsimile jertfelor de mulțumire și cu jertfele de băutură ale arderilor de tot. Astfel a fost așezată din nou slujba Casei DOMNULUI.", "Ezechia și tot poporul s-au bucurat că Dumnezeu făcuse pe popor cu voie bună, căci lucrul s-a făcut pe neașteptate."],
    30: ["Ezechia a trimis soli în tot Israelul și Iuda și a scris scrisori și lui Efraim și lui Manase ca să vină la Casa DOMNULUI la Ierusalim să prăznuiască Paștile în cinstea DOMNULUI Dumnezeului lui Israel.", "Împăratul, căpeteniile lui și toată adunarea ținuseră sfat la Ierusalim, ca Paștile să fie prăznuit în luna a doua;", "căci nu putea fi prăznuit la vremea lui, pentru că preoții nu se sfințiseră în număr destul de mare, și poporul nu se adunase la Ierusalim.", "Lucrul având încuviințarea împăratului și a întregii adunări,", "au hotărât să dea de veste în tot Israelul, de la Beer-Șeba până la Dan, ca să vină la Ierusalim să prăznuiască Paștile în cinstea DOMNULUI Dumnezeului lui Israel. Căci de mult nu mai fusese prăznuit după cum era scris.", "Alergătorii s-au dus cu scrisorile împăratului și căpeteniilor lui în tot Israelul și Iuda. Și, după porunca împăratului, au zis: „Copii ai lui Israel, întoarceți-vă la DOMNUL Dumnezeul lui Avraam, lui Isaac și Israel, ca să Se întoarcă și El la voi, rămășiță scăpată din mâna împăraților Asiriei.”", "Nu fiți ca părinții voștri și ca frații voștri, care au păcătuit împotriva DOMNULUI Dumnezeului părinților lor, și pe care de aceea i-a dat pradă pustiirii, cum vedeți.", "Nu vă înțepeniți grumazul ca părinții voștri; dați mâna DOMNULUI, veniți la Sfântul Lui Locaș, pe care l-a sfințit pe vecie, și slujiți DOMNULUI Dumnezeului vostru, pentru ca mânia Lui aprinsă să se abată de la voi.", "„Dacă vă întoarceți la DOMNUL, frații voștri și fiii voștri vor găsi milă la cei ce i-au luat robi și se vor întoarce în țară. Căci DOMNUL Dumnezeul vostru este milostiv și îndurător și nu-Și va întoarce fața de la voi, dacă vă întoarceți la El.”", "Alergătorii au mers astfel din cetate în cetate prin țara lui Efraim și Manase până la Zabulon. Dar ei râdeau și își băteau joc de ei.", "Însă câțiva oameni din Așer, din Manase și Zabulon s-au smerit și au venit la Ierusalim.", "În Iuda, de asemenea, mâna lui Dumnezeu a lucrat și le-a dat o singură inimă, ca să-i facă să împlinească porunca împăratului și a căpeteniilor, după cuvântul DOMNULUI.", "Un popor în mare număr s-a adunat la Ierusalim să prăznuiască sărbătoarea Azimelor în luna a doua: a fost o adunare foarte mare.", "S-au sculat și au îndepărtat altarele pe care se jertfea în Ierusalim și pe toate acelea pe care se aducea tămâie și le-au aruncat în pârâul Chedron.", "Au jertfit apoi paștile în ziua a paisprezecea a lunii a doua. Preoții și leviții, plini de rușine, s-au sfințit și au adus arderi de tot în Casa DOMNULUI.", "Ei stăteau în locul lor obișnuit, după Legea lui Moise, omul lui Dumnezeu, și preoții stropeau sângele pe care-l luau din mâna leviților.", "Fiindcă în adunare erau mulți inși care nu se sfințiseră, leviții au înjunghiat ei jertfele de Paști pentru toți cei ce nu erau curați, ca să le închine DOMNULUI.", "Căci o mare parte din popor, mulți din Efraim, Manase, Isahar și Zabulon, nu se curățaseră și au mâncat paștile nu după cele scrise. Dar Ezechia s-a rugat pentru ei, zicând: „DOMNUL, care este bun, să ierte pe toți”", "„cei ce și-au pus inima să caute pe DOMNUL Dumnezeul părinților lor, măcar că n-au făcut sfânta curățare!”", "DOMNUL a ascultat pe Ezechia și a vindecat poporul.", "Astfel copiii lui Israel care se aflau la Ierusalim au prăznuit sărbătoarea Azimelor șapte zile, cu mare bucurie. Și în fiecare zi leviții și preoții lăudau pe DOMNUL cu instrumente care răsunau în cinstea Lui.", "Ezechia a vorbit inimii tuturor leviților, care arătau o mare pricepere pentru slujba DOMNULUI. Au mâncat sărbătoarea timp de șapte zile, aducând jertfe de mulțumire și mărturisindu-se DOMNULUI Dumnezeul părinților lor.", "Toată adunarea a fost de părere să mai prăznuiască alte șapte zile. Și au prăznuit cu bucurie încă șapte zile.", "Căci Ezechia, împăratul lui Iuda, dăduse adunării o mie de viței și șapte mii de oi. Iar căpeteniile i-au dat o mie de viței și zece mii de oi, și mulți preoți se sfințiseră.", "Și s-a bucurat toată adunarea lui Iuda, și preoții, și leviții, și tot poporul venit din Israel, și străinii veniți din țara lui Israel sau așezați în Iuda.", "A fost mare veselie la Ierusalim. De pe vremea lui Solomon, fiul lui David, împăratul lui Israel, nu mai fusese la Ierusalim așa ceva.", "Preoții și leviții s-au sculat și au binecuvântat poporul. Glasul lor a fost auzit, și rugăciunea lor a ajuns până la ceruri, până la locuința sfântă a DOMNULUI."],
    31: ["Când s-au isprăvit toate acestea, toți cei din Israel care erau de față au plecat în cetățile lui Iuda și au sfărâmat stâlpii idolești, au tăiat stâlpii Așerei și au surpat de tot înălțimile și altarele din tot Iuda și Beniamin și din Efraim și Manase. Apoi toți copiii lui Israel s-au întors în cetățile lor, fiecare la moșia lui.", "Ezechia a așezat din nou cetele preoților și leviților, după șirul lor, fiecare după slujbele sale, preoți și leviți, pentru arderile de tot și jertfele de mulțumire, pentru slujbă, pentru cântări și laude, la porțile taberei DOMNULUI.", "Împăratul a dat o parte din averile lui pentru arderi de tot, pentru arderile de tot de dimineață și de seară și pentru arderile de tot din zilele de Sabat, de lună nouă și de sărbători, cum este scris în Legea DOMNULUI.", "Și a poruncit poporului, locuitorilor Ierusalimului, să dea preoților și leviților partea cuvenită lor, ca să țină cu scumpătate Legea DOMNULUI.", "Când a ieșit porunca aceasta, copiii lui Israel au dat din belșug cele dintâi roade de grâu, de must, de untdelemn, de miere și din toate roadele de pe câmp; au adus din belșug și zeciuiala din toate.", "Totodată, copiii lui Israel și Iuda care locuiau în cetățile lui Iuda au dat zeciuiala din boi și oi și zeciuiala din lucrurile sfinte care erau închinate DOMNULUI Dumnezeului lor și au făcut mai multe grămezi.", "Au început să facă grămezile în luna a treia și au isprăvit în luna a șaptea.", "Ezechia și căpeteniile au venit să vadă grămezile și au binecuvântat pe DOMNUL și pe poporul Său, Israel.", "Și Ezechia a întrebat pe preoți și pe leviți de grămezile acestea.", "Atunci marele preot Azaria, din casa lui Țadoc, i-a răspuns: „De când au început să se aducă darurile în Casa DOMNULUI, noi am mâncat, ne-am săturat și a mai rămas mult, căci DOMNUL a binecuvântat pe poporul Său. Și iată ce mare grămadă a mai rămas.”", "Ezechia a dat poruncă să pregătească niște cămări în Casa DOMNULUI; și le-au pregătit.", "Au adus în ele cu credincioșie darurile de mâncare, zeciuiala și lucrurile sfinte. Levitul Conania avea grija lor, și fratele său Șimei era al doilea după el.", "Iehiel, Azazia, Nahat, Asael, Ierimot, Iozabad, Eliel, Ismachia, Mahat și Benaia erau întrebuințați sub cârmuirea lui Conania și a fratelui său Șimei, după porunca împăratului Ezechia și a lui Azaria, căpetenia Casei lui Dumnezeu.", "Levitul Core, fiul lui Imna, ușier în partea de răsărit, avea grijă de darurile de bunăvoie aduse lui Dumnezeu, ca să împartă ce era adus DOMNULUI prin ridicare și lucrurile preasfinte.", "În cetățile preoțești, Eden, Miniamin, Iosua, Șemaia, Amaria și Șecania erau puși sub cârmuirea lui ca să împartă cu credincioșie fraților lor, mari și mici, partea cuvenită lor, după cetele lor:", "celor de parte bărbătească înscriși de la vârsta de trei ani în sus; tuturor celor ce intrau zilnic în Casa DOMNULUI ca să-și facă slujba după însărcinările și după cetele lor;", "preoților înscriși după casele lor părintești și leviților de la douăzeci de ani în sus, după slujbele și după cetele lor:", "la toată adunarea preoților și leviților înscriși cu toți pruncii lor, cu nevestele lor, cu fiii și fiicele lor, căci, în slujba lor de încredere, se sfințeau pentru lucrurile sfinte.", "Și pentru fiii lui Aaron, preoții, care locuiau la țară în împrejurimile cetăților lor, erau în fiecare cetate oameni numiți anume ca să împartă părțile cuvenite tuturor celor de parte bărbătească din preoți și tuturor leviților înscriși.", "Iată ce a făcut Ezechia în tot Iuda. El a făcut ce este bine, ce este drept, ce este adevărat, înaintea DOMNULUI Dumnezeului său.", "A lucrat cu toată inima și a izbutit în tot ce a făcut pentru Casa lui Dumnezeu, pentru Lege și pentru porunci, ca să caute pe Dumnezeul său."],
    32: ["După aceste lucruri și după aceste fapte de credincioșie, a venit Sanherib, împăratul Asiriei, care a pătruns în Iuda și a împresurat cetățile întărite, cu gând să pună mâna pe ele.", "Ezechia, văzând că a venit Sanherib și că are de gând să înceapă lupta împotriva Ierusalimului,", "s-a sfătuit cu căpeteniile sale și cu oamenii lui cei viteji ca să astupe izvoarele de apă care erau afară din cetate. Și ei au fost de părerea lui.", "S-au strâns o mulțime de oameni și au astupat toate izvoarele și pârâul care curge prin mijlocul ținutului aceluia. „Pentru ce”, ziceau ei, „să găsească împărații Asiriei, la venirea lor, ape din belșug?”", "Ezechia s-a îmbărbătat; a zidit din nou zidul care era stricat și l-a ridicat până la turnuri. A mai zidit un alt zid în afară, a întărit Milo în cetatea lui David și a pregătit o mulțime de arme și de scuturi.", "A pus căpetenii de război peste popor și i-a adunat la el pe locul deschis de la poarta cetății. Vorbindu-le inimii a zis:", "„Întăriți-vă și îmbărbătați-vă. Nu vă temeți și nu vă înspăimântați înaintea împăratului Asiriei și înaintea întregii mulțimi care este cu el; căci cu noi sunt mai mulți decât cu el.”", "„Cu el este un braț de carne, dar cu noi este DOMNUL Dumnezeul nostru care ne va ajuta și va lupta pentru noi.” Poporul s-a încrezut în cuvintele lui Ezechia, împăratul lui Iuda.", "După aceea, Sanherib, împăratul Asiriei, a trimis pe slujitorii săi la Ierusalim, pe când era înaintea Lachisului cu toate puterile lui; i-a trimis la Ezechia, împăratul lui Iuda, și la toți cei din Iuda care erau la Ierusalim să le spună:", "„Așa vorbește Sanherib, împăratul Asiriei: «Pe ce se bizuie încrederea voastră, de stați împresurați la Ierusalim?»”", "Oare nu vă amăgește Ezechia, ca să vă dea morții prin foamete și prin sete, când zice: „DOMNUL Dumnezeul nostru ne va scăpa din mâna împăratului Asiriei”", "Oare nu Ezechia a îndepărtat înălțimile și altarele DOMNULUI și a dat porunca aceasta lui Iuda și Ierusalimului: „Să vă închinați numai unui altar și să aduceți tămâie numai pe el”", "Nu știți ce am făcut noi, eu și părinții mei, tuturor popoarelor celorlalte țări? Dumnezeii neamurilor acestor țări au putut ei să le izbăvească țările din mâna mea?", "Care dintre toți dumnezeii acestor neamuri, pe care le-au nimicit părinții mei, a putut să izbăvească pe poporul lui din mâna mea, pentru ca să vă poată izbăvi Dumnezeul vostru din mâna mea?", "„Să nu vă amăgească Ezechia, dar, și să nu vă înșele astfel; nu vă încredeți în el! Căci dumnezeul niciunui neam, niciunei împărății n-a putut să izbăvească pe poporul lui din mâna mea și din mâna părinților mei: cu cât mai puțin vă va izbăvi Dumnezeul vostru din mâna mea!”", "Slujitorii lui Sanherib au mai vorbit și alte lucruri împotriva DOMNULUI Dumnezeu și împotriva robului Său Ezechia.", "Și a trimis o scrisoare batjocoritoare pentru DOMNUL Dumnezeul lui Israel, vorbind astfel împotriva Lui: „După cum dumnezeii neamurilor celorlalte țări n-au putut să izbăvească pe poporul lor din mâna mea, tot așa nici Dumnezeul lui Ezechia nu va izbăvi pe poporul Său din mâna mea.”", "Slujitorii lui Sanherib au strigat cu glas tare în limba evreiască, pentru ca să arunce groaza și spaima în poporul din Ierusalim, care era pe zid, și să poată pune astfel stăpânire pe cetate.", "Au vorbit despre Dumnezeul Ierusalimului ca despre dumnezeii popoarelor pământului, care sunt lucrarea mâinilor omenești.", "Împăratul Ezechia și prorocul Isaia, fiul lui Amoț, au început să se roage pentru lucrul acesta și au strigat către cer.", "Atunci DOMNUL a trimis un înger care a nimicit în tabăra împăratului Asiriei pe toți vitejii, domnitorii și căpeteniile. Și împăratul s-a întors rușinat în țara lui. A intrat în casa dumnezeului său, și cei ce ieșiseră din coapsele lui l-au ucis acolo cu sabia.", "Astfel a scăpat DOMNUL pe Ezechia și pe locuitorii Ierusalimului din mâna lui Sanherib, împăratul Asiriei, și din mâna tuturor și i-a ocrotit împotriva celor ce-i împresurau.", "Mulți au adus DOMNULUI daruri în Ierusalim și au adus daruri bogate lui Ezechia, împăratul lui Iuda, care de atunci s-a înălțat în ochii tuturor popoarelor.", "În vremea aceea, Ezechia a fost bolnav de moarte. El a făcut o rugăciune DOMNULUI. DOMNUL i-a vorbit și i-a dat un semn.", "Dar Ezechia n-a răsplătit binefacerea pe care a primit-o, căci i s-a îngâmfat inima. Mânia DOMNULUI a venit peste el, peste Iuda și peste Ierusalim.", "Atunci Ezechia s-a smerit din mândria lui, împreună cu locuitorii Ierusalimului, și mânia DOMNULUI n-a venit peste ei în timpul vieții lui Ezechia.", "Ezechia a avut multe bogății și multă slavă. Și-a făcut vistierii de argint, de aur, de pietre scumpe, de mirodenii, de scuturi și de toate lucrurile care se pot dori;", "hambare pentru roadele de grâu, de must și de untdelemn, grajduri pentru tot felul de vite și staule pentru oi.", "Și-a zidit cetăți și a avut belșug de boi și de oi; căci Dumnezeu îi dăduse multe avuții.", "Tot Ezechia a astupat și gura de sus a apelor Ghihon și le-a adus în jos, spre apus de cetatea lui David. Ezechia a izbutit în toate lucrările lui.", "Însă, când au trimis căpeteniile Babilonului soli la el să întrebe de minunea care avusese loc în țară, Dumnezeu l-a părăsit ca să-l încerce, pentru ca să cunoască tot ce era în inima lui.", "Celelalte fapte ale lui Ezechia și faptele lui evlavioase sunt scrise în vedenia prorocului Isaia, fiul lui Amoț, în cartea împăraților lui Iuda și Israel.", "„Ezechia a adormit cu părinții săi și l-au îngropat în cel mai bun loc al mormintelor fiilor lui David. Tot Iuda și locuitorii Ierusalimului i-au dat cinste la moarte. Și, în locul lui, a domnit fiul său Manase.”"],
    33: ["Manase avea doisprezece ani când a ajuns împărat și a domnit cincizeci și cinci de ani la Ierusalim.", "El a făcut ce este rău înaintea DOMNULUI, după urâciunile neamurilor pe care le izgonise DOMNUL dinaintea copiilor lui Israel.", "A zidit iarăși înălțimile pe care le dărâmase tatăl său, Ezechia. A ridicat altare Baalilor, a făcut stâlpi ai Așerei și s-a închinat înaintea întregii oștiri a cerurilor și i-a slujit.", "A zidit altare în Casa DOMNULUI, măcar că DOMNUL zisese: „În Ierusalim va fi Numele Meu pe vecie.”", "A zidit altare întregii oștiri a cerurilor, în cele două curți ale Casei DOMNULUI.", "Și-a trecut fiii prin foc în valea fiilor lui Hinom, umbla cu descântece și vrăjitorii și ținea la el oameni care chemau duhurile și care-i spuneau viitorul. A făcut din ce în ce mai mult ce este rău înaintea DOMNULUI, ca să-L mânie.", "A pus chipul cioplit al idolului pe care-l făcuse în Casa lui Dumnezeu, despre care Dumnezeu spusese lui David și fiului său Solomon: „În Casa aceasta și în Ierusalim, pe care l-am ales din toate semințiile lui Israel, Îmi voi pune Numele pe vecie.”", "„Nu voi mai strămuta pe Israel din țara pe care am dat-o părinților voștri, numai să caute să împlinească tot ce le-am poruncit, după toată Legea, învățăturile și poruncile date prin Moise.”", "Dar Manase a fost pricina că Iuda și locuitorii Ierusalimului s-au rătăcit și au făcut rău mai mult decât neamurile pe care le nimicise DOMNUL dinaintea copiilor lui Israel.", "DOMNUL a vorbit lui Manase și poporului său, dar ei n-au vrut să asculte.", "Atunci DOMNUL a trimis împotriva lor pe căpeteniile oștirii împăratului Asiriei, care au prins pe Manase și l-au pus în lanțuri. L-au legat cu lanțuri de aramă și l-au dus la Babilon.", "Când a fost la strâmtorare, s-a rugat DOMNULUI Dumnezeului lui și s-a smerit adânc înaintea Dumnezeului părinților săi.", "I-a făcut rugăciuni; și DOMNUL, lăsându-Se înduplecat, i-a ascultat cererile și l-a adus înapoi la Ierusalim în împărăția lui. Și Manase a cunoscut că DOMNUL este Dumnezeu.", "După aceea, a zidit afară din cetatea lui David, la apus, spre Ghihon, în vale, un zid care se întindea până la poarta peștilor și cu care a înconjurat dealul și l-a făcut foarte înalt. A pus și căpetenii de război în toate cetățile întărite ale lui Iuda.", "A înlăturat din Casa DOMNULUI dumnezeii străini și chipul cioplit, a dărâmat toate altarele pe care le zidise pe muntele Casei DOMNULUI și la Ierusalim și le-a aruncat afară din cetate.", "A așezat din nou altarul DOMNULUI, a adus pe el jertfe de mulțumire și de laudă și a poruncit lui Iuda să slujească DOMNULUI Dumnezeului lui Israel.", "Poporul jertfea tot pe înălțimi, dar numai DOMNULUI Dumnezeului său.", "Celelalte fapte ale lui Manase, rugăciunea lui către Dumnezeul lui și cuvintele prorocilor care i-au vorbit în Numele DOMNULUI Dumnezeului lui Israel sunt scrise în faptele împăraților lui Israel.", "Rugăciunea lui și felul în care l-a ascultat Dumnezeu, păcatele și nelegiuirile lui, locurile unde a zidit înălțimi și a înălțat stâlpi ai Așerei și chipuri cioplite, înainte de a se smeri, sunt scrise în cartea lui Hozai.", "Manase a adormit cu părinții săi și a fost îngropat în casa lui. Și, în locul lui, a domnit fiul său Amon.", "Amon avea douăzeci și doi de ani când a ajuns împărat și a domnit doi ani la Ierusalim.", "El a făcut ce este rău înaintea DOMNULUI, cum făcuse tatăl său, Manase. A adus jertfe tuturor chipurilor cioplite pe care le făcuse tatăl său, Manase, și le-a slujit.", "Și nu s-a smerit înaintea DOMNULUI, cum se smerise tatăl său, Manase, căci Amon s-a făcut din ce în ce mai vinovat.", "Slujitorii lui au uneltit împotriva lui și l-au omorât în casa lui.", "Dar poporul țării a ucis pe toți cei ce uneltiseră împotriva împăratului Amon. Și, în locul lui, poporul țării a pus împărat pe fiul său Iosia."],
    34: ["Iosia avea opt ani când a ajuns împărat și a domnit treizeci și unu de ani la Ierusalim.", "El a făcut ce este bine înaintea DOMNULUI și a umblat în căile tatălui său David: nu s-a abătut de la ele nici la dreapta, nici la stânga.", "În al optulea an al domniei lui, pe când era încă tânăr, a început să caute pe Dumnezeul tatălui său David. Și în al doisprezecelea an, a început să curețe Iuda și Ierusalimul de înălțimi, de stâlpii Așerei, de chipuri cioplite și de chipuri turnate.", "Au dărâmat înaintea lui altarele Baalilor și au tăiat stâlpii închinați soarelui care erau deasupra lor; a sfărâmat stâlpii Așerei, chipurile cioplite și chipurile turnate, le-a făcut praf, a presărat praful pe mormintele celor ce le aduseseră jertfe.", "și a ars oasele preoților pe altarele lor. Astfel a curățat Iuda și Ierusalimul.", "În cetățile lui Manase, lui Efraim, lui Simeon și chiar lui Neftali, pretutindeni, în mijlocul dărâmăturilor lor,", "a dărâmat altarele, a făcut bucăți stâlpii Așerei și chipurile cioplite, le-a făcut praf și a tăiat toți stâlpii închinați soarelui în toată țara lui Israel. Apoi s-a întors la Ierusalim.", "În al optsprezecelea an al domniei lui, după ce a curățat țara și Casa, a trimis pe Șafan, fiul lui Ațalia, pe Maaseia, căpetenia cetății, și pe Ioah, fiul lui Ioahaz, arhivarul, să dreagă Casa DOMNULUI Dumnezeului său.", "S-au dus la marele preot, Hilchia, și au dat argintul adus în Casa lui Dumnezeu, pe care-l strânseseră leviții păzitori ai pragului de la Manase și Efraim și de la toată cealaltă parte a lui Israel, și de la tot Iuda și Beniamin, și de la locuitorii Ierusalimului.", "L-au dat în mâinile meșterilor însărcinați cu facerea lucrării în Casa DOMNULUI. Aceștia l-au dat lucrătorilor care munceau la dregerea Casei DOMNULUI,", "iar ei l-au dat tâmplarilor și zidarilor ca să cumpere pietre cioplite și lemne pentru grinzi și pentru căptușitul clădirilor pe care le stricaseră împărații lui Iuda.", "Oamenii aceștia au lucrat cinstit în lucrul lor. Erau puși sub privegherea lui Iahat și Obadia, leviți din fiii lui Merari, și a lui Zaharia și Meșulam, din fiii chehatiților, ca să dea îndrumări; iar alți leviți, toți pricepuți la instrumentele de cântare,", "Ei erau puși peste purtătorii de poveri și cârmuiau pe toți cei ce făceau lucrarea în orice fel de slujbă. Printre leviți erau logofeți, dregători și ușieri.", "În clipa când au scos argintul care fusese adus în Casa DOMNULUI, preotul Hilchia a găsit cartea Legii DOMNULUI dată prin Moise.", "Atunci Hilchia a luat cuvântul și a zis logofătului Șafan: „Am găsit cartea Legii în Casa DOMNULUI.” Hilchia i-a dat cartea lui Șafan.", "Șafan a adus împăratului cartea. Și, când a dat socoteală împăratului, a zis: „Slujitorii tăi au făcut tot ce li s-a poruncit.”", "„Au strâns argintul care se afla în Casa DOMNULUI și l-au dat în mâinile priveghetorilor și lucrătorilor.”", "Logofătul Șafan a mai spus împăratului: „Preotul Hilchia mi-a dat o carte.” Șafan a citit din ea înaintea împăratului.", "Când a auzit împăratul cuvintele Legii, și-a sfâșiat hainele.", "Și împăratul a dat următoarea poruncă lui Hilchia, lui Ahicam, fiul lui Șafan, lui Abdon, fiul lui Mica, lui Șafan, logofătul, și lui Asaia, slujitorul împăratului:", "„Duceți-vă și întrebați pe DOMNUL pentru mine și pentru rămășița lui Israel și Iuda cu privire la cuvintele cărții acesteia care s-a găsit. Căci mare mânie s-a vărsat peste noi din partea DOMNULUI, pentru că părinții noștri n-au ținut cuvântul DOMNULUI și n-au împlinit tot ce este scris în cartea aceasta.”", "Hilchia și cei trimiși de împărat s-au dus la prorocița Hulda, nevasta lui Șalum, fiul lui Tochehat, fiul lui Hasra, străjerul veșmintelor. Ea locuia la Ierusalim, în cealaltă mahala a cetății. După ce au spus ce aveau de spus,", "ea le-a răspuns: „Așa vorbește DOMNUL Dumnezeul lui Israel: «Spuneți omului care v-a trimis la mine:»”", "„Așa vorbește DOMNUL: «Iată, voi trimite nenorociri peste locul acesta și peste locuitorii lui, și anume toate blestemele scrise în cartea care s-a citit înaintea împăratului lui Iuda.»”", "„Pentru că M-au părăsit și au adus tămâie altor dumnezei, mâniindu-Mă prin toate lucrările mâinilor lor, mânia Mea s-a vărsat asupra acestui loc și nu se va stinge.”", "Dar să spuneți împăratului lui Iuda care v-a trimis să întrebați pe DOMNUL: „Așa vorbește DOMNUL Dumnezeul lui Israel cu privire la cuvintele pe care le-ai auzit:”", "„Pentru că ți s-a înduioșat inima, pentru că te-ai smerit înaintea lui Dumnezeu, când ai auzit cuvintele rostite de El împotriva acestui loc și împotriva locuitorilor lui, pentru că te-ai smerit înaintea Mea, pentru că ți-ai sfâșiat hainele și ai plâns înaintea Mea, și Eu am auzit, zice DOMNUL.”", "„Iată, te voi strânge lângă părinții tăi, vei fi adăugat în pace în mormântul tău și nu vei vedea cu ochii tăi toate nenorocirile pe care le voi trimite peste locul acesta și peste locuitorii lui.”", "Împăratul a strâns pe toți bătrânii din Iuda și din Ierusalim.", "Apoi s-a suit la Casa DOMNULUI cu toți oamenii lui Iuda și cu locuitorii Ierusalimului, cu preoții și leviții și cu tot poporul, de la cel mai mare până la cel mai mic. A citit înaintea lor toate cuvintele cărții legământului care se găsise în Casa DOMNULUI.", "Împăratul stătea pe scaunul lui împărătesc și a încheiat legământ înaintea DOMNULUI, îndatorându-se să urmeze pe DOMNUL și să păzească poruncile Lui, învățăturile Lui și legile Lui din toată inima și din tot sufletul lui și să împlinească cuvintele legământului scrise în cartea aceasta.", "Și a făcut să intre în legământ toți cei ce se aflau la Ierusalim și în Beniamin. Și locuitorii Ierusalimului au lucrat după legământul lui Dumnezeu, legământul Dumnezeului părinților lor.", "Iosia a îndepărtat toate urâciunile din toate țările copiilor lui Israel și a făcut ca toți cei ce se aflau în Israel să slujească DOMNULUI Dumnezeului lor. În tot timpul vieții lui, nu s-au abătut de la DOMNUL Dumnezeul părinților lor."],
    35: ["Iosia a prăznuit Paștile în cinstea DOMNULUI la Ierusalim și au jertfit paștile în a paisprezecea zi a lunii întâi.", "A pus pe preoți în slujbele lor și i-a îmbărbătat la slujba Casei DOMNULUI.", "A zis leviților, care învățau pe tot Israelul și care erau închinați DOMNULUI: „Puneți chivotul sfânt în Casa pe care a zidit-o Solomon, fiul lui David, împăratul lui Israel. N-aveți să-l mai purtați pe umeri. Slujiți acum DOMNULUI Dumnezeului vostru și poporului Său, Israel.”", "Pregătiți-vă, după casele voastre părintești, după cetele voastre, cum au rânduit prin scris David, împăratul lui Israel, și fiul său Solomon.", "Luați-vă locurile în Sfântul Locaș, după feluritele case părintești ale fraților voștri, fiii poporului, și după înșiruirea caselor părintești ale leviților.", "„Jertfiți paștile, sfințiți-vă și pregătiți-le pentru frații voștri, întocmai după cuvântul DOMNULUI rostit prin Moise.”", "Iosia a dat oamenilor poporului, tuturor celor ce se aflau acolo, miei și capre în număr de treizeci de mii, toți pentru Paști, și trei mii de boi. Aceștia au fost luați din averile împăratului.", "Căpeteniile lui au făcut de bunăvoie un dar poporului, preoților și leviților. Hilchia, Zaharia și Iehiel, mai marii Casei lui Dumnezeu, au dat preoților, pentru Paști, două mii șase sute de miei și trei sute de boi.", "Conania, Șemaia și Netaneel, frații săi Hașabia, Ieiel și Iozabad, capii leviților, au dat leviților, pentru Paști, cinci mii de miei și cinci sute de boi.", "Astfel s-a întocmit slujba, și preoții și leviții și-au luat locul, după cetele lor, după porunca împăratului.", "Au jertfit paștile. Preoții au stropit sângele pe care-l luau din mâna leviților, și leviții au jupuit vitele de piele.", "Au pus deoparte arderile de tot, ca să le dea cetelor caselor părintești ale oamenilor din popor, ca să le aducă DOMNULUI, cum este scris în cartea lui Moise. Tot așa au făcut și cu boii.", "Au fiert paștile la foc, după orânduială, și au fiert lucrurile sfinte în cazane, căldări și tigăi. Și le-au împărțit în grabă la tot poporul.", "Apoi au pregătit ce era pentru ei și pentru preoți, căci preoții, fiii lui Aaron, au avut treabă până noaptea cu aducerea arderilor de tot și a grăsimilor. De aceea au pregătit leviții pentru ei și pentru preoți, fiii lui Aaron.", "Cântăreții, fiii lui Asaf, stăteau la locul lor, după rânduiala lui David, lui Asaf, lui Heman și lui Iedutun, văzătorul împăratului. Ușierii de asemenea erau la fiecare ușă. N-au avut nevoie să se abată de la slujba lor, căci frații lor, leviții, au pregătit ce era pentru ei.", "Astfel a fost întocmită în ziua aceea toată slujba DOMNULUI, ca să prăznuiască Paștile și să aducă arderile de tot pe altarul DOMNULUI, după porunca împăratului Iosia.", "Copiii lui Israel care se aflau acolo au prăznuit Paștile în același timp și sărbătoarea Azimelor șapte zile.", "Nicio sărbătoare a Paștilor nu mai fusese prăznuită ca aceasta în Israel din zilele prorocului Samuel. Și niciunul din împărații lui Israel nu mai prăznuise Paști ca cel pe care l-au prăznuit Iosia, preoții și leviții, tot Iuda și Israelul care se aflau acolo și locuitorii Ierusalimului.", "În al optsprezecelea an al domniei lui Iosia a fost prăznuit Paștile acesta.", "După toate aceste lucruri, după ce a dres Iosia Casa DOMNULUI, Neco, împăratul Egiptului, s-a suit să lupte împotriva Carchemișului pe Eufrat. Iosia i-a ieșit înainte.", "Și Neco i-a trimis soli să-i spună: „Ce am eu cu tine, împăratul lui Iuda? Nu împotriva ta vin astăzi; ci împotriva unei case cu care sunt în război. Și Dumnezeu mi-a spus să mă grăbesc. Nu te împotrivi lui Dumnezeu, care este cu mine, ca să nu te nimicească.”", "Dar Iosia nu s-a întors de la el, ci și-a schimbat hainele ca să lupte împotriva lui, fără să asculte cuvintele lui Neco care veneau din gura lui Dumnezeu. A înaintat la luptă în valea Meghido.", "Arcașii au tras asupra împăratului Iosia, și împăratul a zis slujitorilor săi: „Luați-mă, căci sunt greu rănit.”", "Slujitorii l-au luat din car, l-au pus într-un alt car al lui și l-au adus la Ierusalim. A murit și a fost îngropat în mormântul părinților săi. Tot Iuda și Ierusalimul au plâns pe Iosia.", "Ieremia a făcut un cântec de jale pentru Iosia. Toți cântăreții și toate cântărețele au vorbit de Iosia în cântecele lor de jale până în ziua de azi și au ajuns o datină în Israel. Cântările acestea sunt scrise în „Cântecele de jale”.", "Celelalte fapte ale lui Iosia și faptele lui evlavioase, făcute așa cum poruncește Legea DOMNULUI,", "cele dintâi și cele de pe urmă fapte ale lui, sunt scrise în cartea împăraților lui Israel și Iuda."],
    36: ["Poporul țării a luat pe Ioahaz, fiul lui Iosia, și l-a pus împărat în locul tatălui său la Ierusalim.", "Ioahaz avea douăzeci și trei de ani când a ajuns împărat și a domnit trei luni la Ierusalim.", "Împăratul Egiptului l-a dat jos de pe scaunul de domnie din Ierusalim și a pus peste țară un bir de o sută de talanți de argint și de un talant de aur.", "Împăratul Egiptului a pus împărat peste Iuda și peste Ierusalim pe Eliachim, fratele lui Ioahaz, și i-a schimbat numele în Ioiachim. Neco a luat pe fratele său Ioahaz și l-a dus în Egipt.", "Ioiachim avea douăzeci și cinci de ani când a ajuns împărat și a domnit unsprezece ani la Ierusalim. El a făcut ce este rău înaintea DOMNULUI Dumnezeului său.", "Nebucadnețar, împăratul Babilonului, s-a suit împotriva lui și l-a legat cu lanțuri de aramă ca să-l ducă la Babilon.", "Nebucadnețar a dus la Babilon unelte din Casa DOMNULUI și le-a pus în casa lui în Babilon.", "Celelalte fapte ale lui Ioiachim, urâciunile pe care le-a săvârșit și răul ce se afla în el, sunt scrise în cartea împăraților lui Israel și Iuda. Și, în locul lui, a domnit fiul său Ioiachin.", "Ioiachin avea opt ani când a ajuns împărat și a domnit trei luni și zece zile la Ierusalim. El a făcut ce este rău înaintea DOMNULUI.", "În anul următor, împăratul Nebucadnețar l-a dus la Babilon împreună cu uneltele scumpe ale Casei DOMNULUI. Și a pus împărat peste Iuda și peste Ierusalim pe Zedechia, fratele lui Ioiachin.", "Zedechia avea douăzeci și unu de ani când a ajuns împărat și a domnit unsprezece ani la Ierusalim.", "El a făcut ce este rău înaintea DOMNULUI Dumnezeului său; și nu s-a smerit înaintea prorocului Ieremia, care-i vorbea din partea DOMNULUI.", "S-a răsculat chiar împotriva împăratului Nebucadnețar, care-l pusese să jure pe Numele lui Dumnezeu. Și-a înțepenit grumazul și și-a învârtoșat inima până acolo încât nu s-a întors la DOMNUL Dumnezeul lui Israel.", "Toate căpeteniile preoților și poporul au înmulțit și ei fărădelegile, după toate urâciunile neamurilor; și au pângărit Casa DOMNULUI, pe care o sfințise El în Ierusalim.", "DOMNUL Dumnezeul părinților lor le trimitea din vreme pe trimișii Săi să-i înștiințeze, căci voia să cruțe pe poporul Său și Locașul Său.", "Dar ei și-au bătut joc de trimișii lui Dumnezeu, I-au nesocotit cuvintele și au râs de prorocii Lui, până când mânia DOMNULUI împotriva poporului Său a ajuns fără leac.", "Atunci DOMNUL a făcut să se suie împotriva lor împăratul haldeilor și a ucis cu sabia pe tinerii lor în casa Locașului lor celui Sfânt. N-a cruțat nici pe tânăr, nici pe tânără, nici pe bătrân, nici pe omul gârbov sub povara perilor albi, ci a dat totul în mâna lui.", "Nebucadnețar a dus la Babilon toate uneltele din Casa DOMNULUI, mari și mici, vistieriile Casei DOMNULUI și vistieriile împăratului și ale căpeteniilor lui.", "Au ars Casa lui Dumnezeu, au dărâmat zidurile Ierusalimului, au pus foc tuturor palatelor lui și au nimicit toate vasele lui de preț.", "Pe cei ce au scăpat de sabie, Nebucadnețar i-a dus prinși la Babilon. Ei i-au fost supuși, lui și fiilor lui, până la stăpânirea împărăției perșilor,", "ca să se împlinească cuvântul DOMNULUI rostit prin gura lui Ieremia, până ce țara și-a ținut Sabatele ei și s-a odihnit tot timpul cât a fost pustiită, până la împlinirea celor șaptezeci de ani.", "În cel dintâi an al lui Cirus, împăratul perșilor, ca să se împlinească cuvântul DOMNULUI rostit prin gura lui Ieremia, DOMNUL a trezit duhul lui Cirus, împăratul perșilor, care a pus să se facă prin viu grai și prin scris această vestire în toată împărăția lui:", "„Așa vorbește Cirus, împăratul perșilor: «DOMNUL Dumnezeul cerurilor mi-a dat toate împărățiile pământului și mi-a poruncit să-I zidesc o Casă la Ierusalim în Iuda. Cine dintre voi este din poporul Lui? DOMNUL Dumnezeul lui să fie cu el și să plece!»”"],
  },
}
